INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l26',3,6,26,'Wanted: A Giant Cookie','征购大饼干','动名词作宾语(avoid / enjoy / mind + doing;It''s no use / not worth + doing)、go / turn / grow + 形容词(变得…)、in the way / on the way / by the way 三个短语的意思、send / lend / give sth to sb、one 与 a 的区别、so + 形容词 + that / such (a) + 名词 + that(原创承载 NCE3 L26 考点·无需净化·广告如何影响人 + 电台''谁烤的饼干最大''比赛:大学生烤出2400磅巨饼夺魁)','谁都躲不开广告的影响。尽管我们自诩品味不俗,却早已不能完全自由地选择想要的东西了,因为广告对我们有一种微妙的作用。为了劝我们买这买那,广告商仔细研究了人性,把我们所有的小弱点都归了类。广告商很早就发现:我们人人都喜欢“不劳而获”。一则以“免费”二字开头的广告几乎从不失手。如今,商家不光送免费样品,还送免费汽车、免费房子、免费环球旅行;他们设计出成百上千种比赛,让我们有机会赢得大笔奖金。广播和电视让广告商得以借此抓住千百万人的注意力。有一次电台节目里,一家饼干厂请听众自己烤饼干寄到厂里,并承诺按每磅十美元收购听众烤出的最大饼干。反响热烈极了。没过多久,各种形状大小的饼干纷纷寄到。一位女士用独轮车把她的饼干推了进来,足足有近五百磅。稍后又来了个男人,他的饼干塞满了整个汽车后备箱。每块饼干都被仔细称重。当时最大的是713磅,看来十拿九稳能得奖。可就在比赛截止前,一辆卡车开进厂里,车上是一块重达2400磅的超级大饼干——出自一个大学生之手,他用了一千多磅面粉、八百磅糖、还有几百磅别的配料。饼干太重,只好动用起重机才把它从卡车上吊下来。厂家最后付的钱远超预料:他们花两万四千美元买下了这块饼干。','{"q":"Listen and answer — Who won the prize for the biggest cookie?","options":["A college student","A woman with a wheelbarrow","A man with a big car","The radio host"],"answer_index":0}'::jsonb,'{"title":"动名词作宾语 / go·turn·grow+形容词 / send sth to sb / so...that","intro":"①有些词后面要接动名词 -ing:avoid doing、enjoy doing、mind doing;It''s no use doing、It''s not worth doing。②go / turn / grow + 形容词表示“变得…”:go wrong(出错)、go bad(变坏)、turn yellow(变黄)、grow quiet(变安静)。③三个短语意思不同:in the way(挡道)、on the way(在途中)、by the way(顺便说)。④send / lend / give + 某物 + to + 某人。⑤one 强调“一个(数量、具体某个)”,a 泛指“一个”。⑥so + 形容词 + that;such + (a) + 名词 + that。","table":{"headers":["用法","意思","例子"],"rows":[["avoid/mind doing · It''s no use doing","后接动名词","avoid being influenced"],["go / turn / grow + 形容词","变得…","go wrong / turn yellow"],["in / on / by the way","挡道 / 途中 / 顺便说","by the way, …"],["send/give sth to sb · so...that","把…给… / 如此…以致","send them to the factory / so heavy that…"]]},"specialRules":[{"rule":"avoid / mind / enjoy 后面接 -ing,不接 to do:avoid being influenced(✓)avoid to be(✗)。","mark":"avoid/mind + doing"},{"rule":"go / turn / grow 表“变得…”时后面接形容词(不接 to);go bad / turn cold。","mark":"go/turn/grow + 形容词"},{"rule":"美式用词:cookie(英式 biscuit)、trunk(汽车后备箱,英式 boot)、truck(英式 lorry)。本课已按美语写。","mark":"cookie / trunk / truck"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l26',1,NULL,'No one can avoid being influenced by advertisements. Much as we may pride ourselves on our good taste, we are no longer free to choose exactly what we want, for advertising has a subtle effect on us. In their efforts to persuade us to buy this or that product, advertisers have made a careful study of human nature and have classified all our little weaknesses.','谁都躲不开广告的影响。尽管我们自诩品味不俗,却早已不能完全自由地选择想要的东西了,因为广告对我们有一种微妙的作用。为了劝我们买这买那,广告商仔细研究了人性,把我们所有的小弱点都归了类。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l26',2,NULL,'Advertisers discovered long ago that all of us love to get something for nothing. An ad that begins with the magic word FREE can rarely go wrong. These days, companies offer not only free samples but free cars, free houses, and free trips around the world. They dream up hundreds of contests that promise us the chance to win huge sums of money. Radio and television have made it possible to capture the attention of millions of people this way.','广告商很早就发现:我们人人都喜欢“不劳而获”。一则以“免费”二字开头的广告几乎从不失手。如今,商家不光送免费样品,还送免费汽车、房子、环球旅行;他们设计出成百上千种比赛,让我们有机会赢得大笔奖金。广播和电视让广告商得以借此抓住千百万人的注意力。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l26',3,NULL,'During a radio show, a company of cookie makers once asked listeners to bake cookies and send them to the factory. They offered ten dollars a pound for the biggest cookie a listener could bake. The response was tremendous. Before long, cookies of every shape and size began arriving.','有一次电台节目里,一家饼干厂请听众自己烤饼干寄到厂里,并承诺按每磅十美元收购听众烤出的最大饼干。反响热烈极了。没过多久,各种形状大小的饼干纷纷寄到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l26',4,NULL,'One woman wheeled hers in on a wheelbarrow; it weighed nearly 500 pounds. A little later, a man showed up with a cookie that filled the entire trunk of his car. Every cookie was carefully weighed. The largest so far was 713 pounds, and it seemed certain to win.','一位女士用独轮车把她的饼干推了进来,足足有近五百磅。稍后又来了个男人,他的饼干塞满了整个汽车后备箱。每块饼干都被仔细称重。当时最大的是713磅,看来十拿九稳能得奖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l26',5,NULL,'But just before the contest closed, a truck pulled up with a truly colossal cookie weighing 2,400 pounds. It had been baked by a college student who had used over a thousand pounds of flour, 800 pounds of sugar, and hundreds of pounds of other ingredients. It was so heavy that a crane had to be used to lift it off the truck. The company ended up paying far more than they had anticipated: they bought that cookie for $24,000.','可就在比赛截止前,一辆卡车开进厂里,车上是一块重达2400磅的超级大饼干——出自一个大学生之手,他用了一千多磅面粉、八百磅糖、还有几百磅别的配料。饼干太重,只好动用起重机才把它从卡车上吊下来。厂家最后付的钱远超预料:他们花两万四千美元买下了这块饼干。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
