INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l26','something for nothing','',NULL,'/ˈsʌmθɪŋ fɔːr ˈnʌθɪŋ/','We all love to get something for nothing.','我们都喜欢不劳而获。','There''s no such thing as something for nothing.','天下没有免费的午餐。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l26','go wrong','',NULL,'/ɡoʊ rɔːŋ/','An ad with FREE can rarely go wrong.','带''免费''的广告很少失手。','Something went wrong with the plan.','计划出了岔子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l26','before long','',NULL,'/bɪˈfɔːr lɔːŋ/','Before long, cookies began arriving.','没过多久,饼干就纷纷寄到。','We''ll be there before long.','我们不久就到。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l26','pride oneself on','',NULL,'/praɪd wʌnˈself ɑːn/','We pride ourselves on our good taste.','我们自诩品味不俗。','She prides herself on her cooking.','她为自己的厨艺自豪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp1','choice','{"stem":"\"No one can avoid ___ influenced by advertisements.\"(avoid 后接动名词)","options":["be","being","been","to be"],"answer_index":1,"stem_cn":"没人能避免受广告影响。","explanation_cn":"avoid 后面接动名词 -ing;被动的动名词是 being + 过去分词。✓ avoid being influenced. ✗ to be / be / been:avoid 后接 -ing。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp1','choice','{"stem":"\"It''s no use ___ about the weather.\"(It''s no use 后接动名词)","options":["to complain","complain","complained","complaining"],"answer_index":3,"stem_cn":"抱怨天气没有用。","explanation_cn":"It''s no use 后面接动名词 -ing。✓ It''s no use complaining. ✗ to complain / complain / complained:no use 后接 -ing。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp1','choice','{"stem":"\"Would you mind ___ your cookie on the scale?\"(would you mind 后接动名词)","options":["put","putting","to put","puts"],"answer_index":1,"stem_cn":"你介意把饼干放到秤上吗?","explanation_cn":"Would you mind 后面接动名词 -ing。✓ Would you mind putting…? ✗ to put / put / puts:mind 后接 -ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp2','choice','{"stem":"\"An ad that starts with ''FREE'' can rarely ___ wrong.\"(与“出错”搭配、表“变得”的动词)","options":["turn","be","do","go"],"answer_index":3,"stem_cn":"以''免费''开头的广告很少会出错。","explanation_cn":"表“变得(出错)”用 go:go wrong。✓ can rarely go wrong. ✗ be / turn / do:“出错”固定说 go wrong。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp2','choice','{"stem":"\"If you leave milk out, it will soon ___ bad.\"(与“变坏”搭配、表“变得”的动词)","options":["go","make","turn to","become to"],"answer_index":0,"stem_cn":"牛奶放外面很快会变质。","explanation_cn":"表“变坏”用 go bad。✓ milk will go bad. ✗ become to / turn to / make:“变质”用 go bad。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp2','choice','{"stem":"\"In autumn the leaves ___ yellow.\"(与“变黄”搭配、表“变得”的动词)","options":["go to","make","turn","become of"],"answer_index":2,"stem_cn":"秋天树叶变黄。","explanation_cn":"表“(颜色)变…”用 turn:turn yellow。✓ leaves turn yellow. ✗ go to / become of / make:变颜色常用 turn。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp3','choice','{"stem":"\"___ the way, did anyone win the cookie contest?\"(“顺便问一下”)","options":["On","At","In","By"],"answer_index":3,"stem_cn":"顺便问一下,有人赢了饼干比赛吗?","explanation_cn":"“顺便说/顺便问”用 by the way。✓ By the way, … ✗ In / On / At:固定说 by the way。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp3','choice','{"stem":"\"Please move the box; it''s ___ the way.\"(“挡道、碍事”)","options":["by","at","in","on"],"answer_index":2,"stem_cn":"请把箱子挪开,它挡道了。","explanation_cn":"“挡道、碍事”用 in the way。✓ it''s in the way. ✗ on / by / at:“挡道”用 in the way。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp3','choice','{"stem":"\"We stopped for lunch ___ the way to the factory.\"(“在去…的途中”)","options":["in","on","at","by"],"answer_index":1,"stem_cn":"去工厂的路上我们停下来吃了午饭。","explanation_cn":"“在去…的途中”用 on the way。✓ on the way to the factory. ✗ in / by / at:“在途中”用 on the way。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp4','choice','{"stem":"\"Listeners were asked to bake cookies and send them ___ the factory.\"(send sth 后接哪个介词)","options":["with","at","to","for"],"answer_index":2,"stem_cn":"听众被请去烤饼干,寄到工厂。","explanation_cn":"send sth to sb/somewhere,介词用 to。✓ send them to the factory. ✗ for / at / with:send 后接 to。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp4','choice','{"stem":"\"The company gave a big prize ___ the winner.\"(give sth 后接哪个介词)","options":["to","at","of","for"],"answer_index":0,"stem_cn":"公司把大奖发给了获胜者。","explanation_cn":"give sth to sb,介词用 to。✓ gave a prize to the winner. ✗ for / at / of:give 后接 to。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp4','choice','{"stem":"\"Can you lend your scale ___ me for a minute?\"(lend sth 后接哪个介词)","options":["for","at","to","with"],"answer_index":2,"stem_cn":"你能把秤借我用一下吗?","explanation_cn":"lend sth to sb,介词用 to。✓ lend your scale to me. ✗ for / at / with:lend 后接 to。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp5','choice','{"stem":"\"In the whole contest, only ___ student baked the giant winning cookie.\"(强调“仅一个”,数量)","options":["one","an","a","the"],"answer_index":0,"stem_cn":"整场比赛只有一个学生烤出了那块获胜的巨饼。","explanation_cn":"强调“仅一个、具体某个”用 one(数量)。✓ only one student. ✗ a / an(泛指“一个”)/ the:强调数量用 one。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp5','choice','{"stem":"\"The cookie was ___ heavy that a crane was needed.\"(“如此…以致”,形容词前填哪个)","options":["such a","so","very","such"],"answer_index":1,"stem_cn":"那块饼干太重了,得动用起重机。","explanation_cn":"“如此…以致…”里形容词前用 so:so heavy that…。✓ so heavy that a crane was needed. ✗ such / such a(接名词)/ very:形容词前用 so。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp5','choice','{"stem":"\"It was ___ a big cookie that no one could lift it.\"(“那么…的一个…”,名词短语前填哪个)","options":["such","very","so","so a"],"answer_index":0,"stem_cn":"那是块那么大的饼干,谁也搬不动。","explanation_cn":"“那么…的一个…”里名词短语前用 such:such a big cookie。✓ such a big cookie that… ✗ so(接形容词)/ so a / very:名词短语前用 such。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp6','choice','{"stem":"\"A slight, hard-to-notice effect is a ___ one.\"(“微妙的”用哪个词)","options":["heavy","bright","loud","subtle"],"answer_index":3,"stem_cn":"轻微、不易察觉的影响。","explanation_cn":"轻微、不易察觉的是 subtle(微妙的)。✓ a subtle effect. ✗ loud 响;✗ bright 亮;✗ heavy 重——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp6','choice','{"stem":"\"A company that makes products is a ___.\"(“制造商”用哪个词)","options":["reporter","manufacturer","driver","customer"],"answer_index":1,"stem_cn":"生产产品的公司。","explanation_cn":"生产产品的公司是 manufacturer(制造商)。✓ a cookie manufacturer. ✗ customer 顾客;✗ reporter 记者;✗ driver 司机——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',5,'am3_l26_gp6','choice','{"stem":"\"A machine that lifts very heavy things is a ___.\"(“起重机”用哪个词)","options":["wheel","ladder","basket","crane"],"answer_index":3,"stem_cn":"吊起很重东西的机器。","explanation_cn":"吊起很重东西的机器是 crane(起重机)。✓ a crane had to be used. ✗ ladder 梯子;✗ basket 篮子;✗ wheel 轮子——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"influence 的意思是:","options":["忽视","影响","隐藏","购买"],"answer_index":1,"explanation_cn":"influence = 影响。✓ influenced by advertisements 受广告影响。\n顺带记:忽视 = ignore;购买 = buy;隐藏 = hide."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"subtle 的意思是:","options":["明显的","巨大的","廉价的","微妙的,难以捉摸的"],"answer_index":3,"explanation_cn":"subtle = 微妙的、难以捉摸的。✓ a subtle effect 微妙的作用。\n顺带记:明显的 = obvious;巨大的 = huge;廉价的 = cheap."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"classify 的意思是:","options":["分类","购买","丢弃","损坏"],"answer_index":0,"explanation_cn":"classify = 分类。✓ classified our weaknesses 把弱点归了类。\n顺带记:丢弃 = throw away;购买 = buy;损坏 = damage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"manufacturer 的意思是:","options":["游客","顾客","制造商","记者"],"answer_index":2,"explanation_cn":"manufacturer = 生产厂家、制造商。✓ a cookie manufacturer.\n顺带记:顾客 = customer;记者 = reporter;游客 = tourist."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"anticipate 的意思是:","options":["忘记","怀疑","庆祝","预期,预料"],"answer_index":3,"explanation_cn":"anticipate = 预期、预料。✓ more than they had anticipated 超出预料。\n顺带记:忘记 = forget;怀疑 = doubt;庆祝 = celebrate."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',6,NULL,'choice','{"stem":"colossal 的意思是:","options":["微小的","昂贵的","巨大的","普通的"],"answer_index":2,"explanation_cn":"colossal = 巨大的。✓ a colossal cookie 一块超大的饼干。\n顺带记:微小的 = tiny;普通的 = ordinary;昂贵的 = expensive."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',7,NULL,'cloze','{"stem":"第 1 空","context":"No one can avoid ___1___ influenced by ads. Advertisers know we all love to get something for nothing, so an ad with ''FREE'' can rarely ___2___ wrong. In one radio contest, a company asked listeners to send giant cookies ___3___ their factory. The winning cookie was ___4___ heavy that a crane had to lift it.","blank_no":1,"options":["being","to be","be","been"],"answer_index":0,"explanation_cn":"avoid 后接动名词,被动用 being + 过去分词。✓ avoid being influenced by ads."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',7,NULL,'cloze','{"stem":"第 2 空","context":"No one can avoid ___1___ influenced by ads. Advertisers know we all love to get something for nothing, so an ad with ''FREE'' can rarely ___2___ wrong. In one radio contest, a company asked listeners to send giant cookies ___3___ their factory. The winning cookie was ___4___ heavy that a crane had to lift it.","blank_no":2,"options":["go","be","turn","do"],"answer_index":0,"explanation_cn":"“出错”用 go wrong。✓ an ad with ''FREE'' can rarely go wrong."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',7,NULL,'cloze','{"stem":"第 3 空","context":"No one can avoid ___1___ influenced by ads. Advertisers know we all love to get something for nothing, so an ad with ''FREE'' can rarely ___2___ wrong. In one radio contest, a company asked listeners to send giant cookies ___3___ their factory. The winning cookie was ___4___ heavy that a crane had to lift it.","blank_no":3,"options":["to","for","at","with"],"answer_index":0,"explanation_cn":"send sth to somewhere,介词用 to。✓ send giant cookies to their factory."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',7,NULL,'cloze','{"stem":"第 4 空","context":"No one can avoid ___1___ influenced by ads. Advertisers know we all love to get something for nothing, so an ad with ''FREE'' can rarely ___2___ wrong. In one radio contest, a company asked listeners to send giant cookies ___3___ their factory. The winning cookie was ___4___ heavy that a crane had to lift it.","blank_no":4,"options":["so","such","such a","very"],"answer_index":0,"explanation_cn":"“如此…以致…”,形容词前用 so。✓ so heavy that a crane had to lift it."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',8,NULL,'choice','{"stem":"Why can advertisers influence us so easily?","options":["They give us direct orders","They have studied human nature and our weaknesses","They lower all prices","They hide their products"],"answer_index":1,"explanation_cn":"课文说 advertisers have made a careful study of human nature and have classified all our little weaknesses——广告商研究人性、归类弱点,所以容易影响我们。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',8,NULL,'choice','{"stem":"What word makes an advertisement rarely go wrong?","options":["SALE","BUY","FREE","NEW"],"answer_index":2,"explanation_cn":"课文说 An ad that begins with the magic word FREE can rarely go wrong——“免费”是让广告几乎不失手的魔力词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',8,NULL,'choice','{"stem":"How was the winning cookie brought to the factory?","options":["On a truck, needing a crane to unload","In a car trunk","On a wheelbarrow","By regular mail"],"answer_index":0,"explanation_cn":"课文说 a truck pulled up…a crane had to be used to lift it off——获胜的饼干用卡车运来、要起重机卸货。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',9,NULL,'choice','{"stem":"你想说\"没人能避免受广告影响\"(avoid + 动名词):","options":["No one can avoid to be influenced by ads.","No one can avoid being influenced by ads.","No one can avoid be influenced by ads.","No one can avoid influenced by ads."],"answer_index":1,"explanation_cn":"avoid 后接动名词,被动用 being + 过去分词。✓ No one can avoid being influenced by ads. 场合:说“无法避免……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',9,NULL,'choice','{"stem":"你想说\"那块饼干太重了,得用起重机\"(so...that):","options":["The cookie was such heavy that a crane was needed.","The cookie was heavy so that a crane was needed.","The cookie was so heavy that a crane was needed.","The cookie was so a heavy that a crane was needed."],"answer_index":2,"explanation_cn":"“如此…以致…”:so + 形容词 + that。✓ The cookie was so heavy that a crane was needed. 场合:说程度高到某种结果。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',9,NULL,'choice','{"stem":"你想说\"请把饼干寄到工厂\"(send sth to somewhere):","options":["Please send the cookies to the factory.","Please send the cookies the factory to.","Please send the cookies for the factory.","Please send the cookies at the factory."],"answer_index":0,"explanation_cn":"send sth to somewhere,介词用 to,语序是 send + 某物 + to + 地点。✓ Please send the cookies to the factory. 场合:请人把东西寄到某处。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"subtle 的意思是:","options":["明显的","廉价的","微妙的,难以捉摸的","巨大的"],"answer_index":2,"explanation_cn":"subtle = 微妙的、难以捉摸的。✓ a subtle effect."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"colossal 的意思是:","options":["昂贵的","巨大的","普通的","微小的"],"answer_index":1,"explanation_cn":"colossal = 巨大的。✓ a colossal cookie."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"\"No one can avoid ___ influenced by ads.\"(avoid + 动名词)","options":["been","to be","be","being"],"answer_index":3,"stem_cn":"没人能避免受广告影响。","explanation_cn":"avoid 后接动名词,被动用 being + 过去分词。✓ avoid being influenced. ✗ to be / be / been:avoid 后接 -ing。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"\"The cookie was ___ heavy that a crane was needed.\"(“如此…以致”结构,形容词前)","options":["such a","such","so","very"],"answer_index":2,"stem_cn":"那块饼干太重了,得用起重机。","explanation_cn":"“如此…以致…”,形容词前用 so。✓ so heavy that a crane was needed. ✗ such / such a（接名词）/ very:形容词前用 so。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"\"something for nothing\" 的意思是:","options":["不劳而获,免费得来的东西","一无所有","无关紧要的事","徒劳无功"],"answer_index":0,"explanation_cn":"something for nothing = 不劳而获、免费得来的东西。✓ love to get something for nothing 喜欢不劳而获。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"\"by the way\" 的意思是:","options":["挡在路上","用这种方法","在半路上","顺便说一句"],"answer_index":3,"explanation_cn":"by the way = 顺便说一句。✓ By the way, … 顺便问一下……。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"How did the college student win the contest?","options":["He was the first to enter","He paid the company","He baked a 2,400-pound cookie","He guessed the right answer"],"answer_index":2,"passage":"No one can avoid being influenced by advertisements. Much as we may pride ourselves on our good taste, we are no longer free to choose exactly what we want, for advertising has a subtle effect on us. In their efforts to persuade us to buy this or that product, advertisers have made a careful study of human nature and have classified all our little weaknesses. Advertisers discovered long ago that all of us love to get something for nothing. An ad that begins with the magic word FREE can rarely go wrong. These days, companies offer not only free samples but free cars, free houses, and free trips around the world. They dream up hundreds of contests that promise us the chance to win huge sums of money. Radio and television have made it possible to capture the attention of millions of people this way. During a radio show, a company of cookie makers once asked listeners to bake cookies and send them to the factory. They offered ten dollars a pound for the biggest cookie a listener could bake. The response was tremendous. Before long, cookies of every shape and size began arriving. One woman wheeled hers in on a wheelbarrow; it weighed nearly 500 pounds. A little later, a man showed up with a cookie that filled the entire trunk of his car. Every cookie was carefully weighed. The largest so far was 713 pounds, and it seemed certain to win. But just before the contest closed, a truck pulled up with a truly colossal cookie weighing 2,400 pounds. It had been baked by a college student who had used over a thousand pounds of flour, 800 pounds of sugar, and hundreds of pounds of other ingredients. It was so heavy that a crane had to be used to lift it off the truck. The company ended up paying far more than they had anticipated: they bought that cookie for $24,000.","explanation_cn":"课文说 a truly colossal cookie weighing 2,400 pounds…baked by a college student——大学生烤了块2400磅的巨饼而夺魁。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"How much did the company pay for the winning cookie?","options":["$713","$2,400","$10","$24,000"],"answer_index":3,"passage":"No one can avoid being influenced by advertisements. Much as we may pride ourselves on our good taste, we are no longer free to choose exactly what we want, for advertising has a subtle effect on us. In their efforts to persuade us to buy this or that product, advertisers have made a careful study of human nature and have classified all our little weaknesses. Advertisers discovered long ago that all of us love to get something for nothing. An ad that begins with the magic word FREE can rarely go wrong. These days, companies offer not only free samples but free cars, free houses, and free trips around the world. They dream up hundreds of contests that promise us the chance to win huge sums of money. Radio and television have made it possible to capture the attention of millions of people this way. During a radio show, a company of cookie makers once asked listeners to bake cookies and send them to the factory. They offered ten dollars a pound for the biggest cookie a listener could bake. The response was tremendous. Before long, cookies of every shape and size began arriving. One woman wheeled hers in on a wheelbarrow; it weighed nearly 500 pounds. A little later, a man showed up with a cookie that filled the entire trunk of his car. Every cookie was carefully weighed. The largest so far was 713 pounds, and it seemed certain to win. But just before the contest closed, a truck pulled up with a truly colossal cookie weighing 2,400 pounds. It had been baked by a college student who had used over a thousand pounds of flour, 800 pounds of sugar, and hundreds of pounds of other ingredients. It was so heavy that a crane had to be used to lift it off the truck. The company ended up paying far more than they had anticipated: they bought that cookie for $24,000.","explanation_cn":"课文说 they bought that cookie for $24,000——厂家花两万四千美元买下获胜饼干。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"What did the radio company make?","options":["Radios","Soap","Cookies","Cars"],"answer_index":2,"audio":"No one can avoid being influenced by advertisements. Much as we may pride ourselves on our good taste, we are no longer free to choose exactly what we want, for advertising has a subtle effect on us. In their efforts to persuade us to buy this or that product, advertisers have made a careful study of human nature and have classified all our little weaknesses. Advertisers discovered long ago that all of us love to get something for nothing. An ad that begins with the magic word FREE can rarely go wrong. These days, companies offer not only free samples but free cars, free houses, and free trips around the world. They dream up hundreds of contests that promise us the chance to win huge sums of money. Radio and television have made it possible to capture the attention of millions of people this way. During a radio show, a company of cookie makers once asked listeners to bake cookies and send them to the factory. They offered ten dollars a pound for the biggest cookie a listener could bake. The response was tremendous. Before long, cookies of every shape and size began arriving. One woman wheeled hers in on a wheelbarrow; it weighed nearly 500 pounds. A little later, a man showed up with a cookie that filled the entire trunk of his car. Every cookie was carefully weighed. The largest so far was 713 pounds, and it seemed certain to win. But just before the contest closed, a truck pulled up with a truly colossal cookie weighing 2,400 pounds. It had been baked by a college student who had used over a thousand pounds of flour, 800 pounds of sugar, and hundreds of pounds of other ingredients. It was so heavy that a crane had to be used to lift it off the truck. The company ended up paying far more than they had anticipated: they bought that cookie for $24,000.","explanation_cn":"课文说 a company of cookie makers——办比赛的是一家饼干厂。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l26',10,NULL,'choice','{"stem":"What did the company think about how much they would pay?","options":["It was more than they had anticipated","It was exactly as planned","They paid nothing at all","It was less than expected"],"answer_index":0,"audio":"No one can avoid being influenced by advertisements. Much as we may pride ourselves on our good taste, we are no longer free to choose exactly what we want, for advertising has a subtle effect on us. In their efforts to persuade us to buy this or that product, advertisers have made a careful study of human nature and have classified all our little weaknesses. Advertisers discovered long ago that all of us love to get something for nothing. An ad that begins with the magic word FREE can rarely go wrong. These days, companies offer not only free samples but free cars, free houses, and free trips around the world. They dream up hundreds of contests that promise us the chance to win huge sums of money. Radio and television have made it possible to capture the attention of millions of people this way. During a radio show, a company of cookie makers once asked listeners to bake cookies and send them to the factory. They offered ten dollars a pound for the biggest cookie a listener could bake. The response was tremendous. Before long, cookies of every shape and size began arriving. One woman wheeled hers in on a wheelbarrow; it weighed nearly 500 pounds. A little later, a man showed up with a cookie that filled the entire trunk of his car. Every cookie was carefully weighed. The largest so far was 713 pounds, and it seemed certain to win. But just before the contest closed, a truck pulled up with a truly colossal cookie weighing 2,400 pounds. It had been baked by a college student who had used over a thousand pounds of flour, 800 pounds of sugar, and hundreds of pounds of other ingredients. It was so heavy that a crane had to be used to lift it off the truck. The company ended up paying far more than they had anticipated: they bought that cookie for $24,000.","explanation_cn":"课文说 had to pay more money than they had anticipated——付的钱超出了他们的预料。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l27',3,6,27,'Nothing to Sell and Nothing to Buy','不卖也不买','It is said that… / sb is said to do…(据说)、不可数名词(knowledge / information / news / advice / work,不加 s、不用 a)、there be 的各种时态(there are / there was / there has been)、目的状语 so that / in order to / so as not to、被动不定式 have to be paid for、介词 + whom / which(原创承载 NCE3 L27 考点·轻净化:去掉原文''偷窃/乞讨''字样,把''流浪汉''改为选择简朴自由的''自在旅人'',保留''人人都在出售什么、唯独他无所求''的思辨内核)','有人说,人人都靠卖点什么为生。这样看来,老师卖的是知识,医生卖的是健康,牧师卖的是慰藉。物品的价值虽可用钱衡量,可别人为我们提供的服务,其真正价值却极难估量。有时候,为了保命我们情愿倾其所有,可事后又会舍不得给做手术的外科大夫一笔高额费用——尽管他给的正是这项服务。社会就是这样安排的:技能也得像商店里的商品一样,花钱去买。看来,人人都有东西可卖。唯有那位自在旅人,似乎是个例外。他和乞丐不同——乞丐某种意义上是把自己的不幸卖出去,换取路人的怜悯;而真正的旅人无物可卖,也不向别人索求什么。他追求独立,却不因此丢掉尊严。他可能向你讨几个钱,却绝不会求你可怜他。他是有意选择了这样的生活,也完全清楚由此带来的后果。他从不确定下一顿饭在哪里,却摆脱了折磨着我们其余人的千万种焦虑。他家当不多,能轻松地四处迁徙;因为睡在露天,他比我们大多数人都更贴近大自然。偶尔在真正需要时,他会做一点活儿,但他绝不会拿自由去交换。我们常带着蔑视谈起这类人,可扪心自问:我们当中,又有几个从没对他们那简单的生活、那份无忧无虑,生出过一丝羡慕呢?','{"q":"Listen and answer — What is the most important thing for the free wanderer?","options":["His freedom","His money","His house","His job"],"answer_index":0}'::jsonb,'{"title":"It is said that / 不可数名词 / there be / 目的状语 / 被动不定式","intro":"①“据说”:It is said that… / He is said to do…(被动报道)。②不可数名词(knowledge, information, news, advice, work, luggage)不加 s、前面不加 a,作主语时动词用单数(The news is good)。③there be 有各种时态:there are / there was / there will be / there has been。④目的状语:so that + 从句(以便);in order to + 动词(为了);so as not to + 动词(以免)。⑤被动不定式 to be done:skills have to be paid for(技能得花钱买)。⑥介词 + whom(指人)/ which(指物):the friend with whom he travels。","table":{"headers":["用法","意思","例子"],"rows":[["It is said that / sb is said to","据说…","It is said that everyone sells something."],["不可数名词","不加 s、不用 a","knowledge / news / advice"],["there be 各时态","有…","there are times / there has been…"],["so that / in order to / to be paid for","以便 / 为了 / 被支付","so that he can move / have to be paid for"]]},"specialRules":[{"rule":"knowledge, information, news, advice, work 都是不可数名词:不能说 an advice / two informations;news 作主语时动词用单数(The news is…)。","mark":"不可数名词"},{"rule":"目的:so that 后接一个从句(有主语和动词);in order to / so as (not) to 后接动词原形。","mark":"so that / in order to"},{"rule":"美式用词:store(英式 shop)、sidewalk(英式 pavement)、downtown(英式 city centre)。本课已按美语写。","mark":"store / sidewalk"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l27',1,NULL,'It has been said that everyone lives by selling something. Seen in this light, teachers live by selling knowledge, doctors by selling health, and priests by selling comfort. Though the value of material goods can be measured in money, it is extremely difficult to estimate the true worth of the services people perform for us.','有人说,人人都靠卖点什么为生。这样看来,老师卖的是知识,医生卖的是健康,牧师卖的是慰藉。物品的价值虽可用钱衡量,可别人为我们提供的服务,其真正价值却极难估量。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l27',2,NULL,'There are times when we would gladly give everything we own to save our lives, and yet we might resent paying a surgeon a large fee for offering us exactly that service. Society is arranged so that skills have to be paid for in the same way that goods have to be paid for in a store. Everyone, it seems, has something to sell.','有时候,为了保命我们情愿倾其所有,可事后又会舍不得给做手术的外科大夫一笔高额费用——尽管他给的正是这项服务。社会就是这样安排的:技能也得像商店里的商品一样,花钱去买。看来,人人都有东西可卖。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l27',3,NULL,'The free-spirited wanderer seems to be the one exception to this rule. Unlike a beggar, who in a sense sells his own misfortune for the pity of passers-by, the true wanderer has nothing to sell and asks nothing of others. In seeking his independence, he does not give up his dignity. He may ask you for a few dollars, but he will never ask you to feel sorry for him.','唯有那位自在旅人,似乎是个例外。他和乞丐不同——乞丐某种意义上是把自己的不幸卖出去,换取路人的怜悯;而真正的旅人无物可卖,也不向别人索求什么。他追求独立,却不因此丢掉尊严。他可能向你讨几个钱,却绝不会求你可怜他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l27',4,NULL,'He has deliberately chosen the life he leads and is fully aware of its consequences. He can never be sure where his next meal is coming from, yet he is free from the thousands of anxieties that afflict the rest of us. With few possessions, he can move from place to place with ease, and by sleeping under the open sky he comes far closer to nature than most of us ever do.','他是有意选择了这样的生活,也完全清楚由此带来的后果。他从不确定下一顿饭在哪里,却摆脱了折磨着我们其余人的千万种焦虑。他家当不多,能轻松地四处迁徙;因为睡在露天,他比我们大多数人都更贴近大自然。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l27',5,NULL,'Now and then, in times of real need, he will do a little work, but he will never trade away his freedom. We often speak of such people with contempt, yet how many of us have never felt just a little envious of their simple life and their freedom from care?','偶尔在真正需要时,他会做一点活儿,但他绝不会拿自由去交换。我们常带着蔑视谈起这类人,可扪心自问:我们当中,又有几个从没对他们那简单的生活、那份无忧无虑,生出过一丝羡慕呢?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
