INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l28','no sooner ... than','',NULL,'/noʊ ˈsuːnər ... ðæn/','I had no sooner got off than a man ran up.','我刚下船,就有人冲了上来。','No sooner had she left than it rained.','她刚走,就下起雨来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l28','get rid of','',NULL,'/ɡet rɪd əv/','It took me half an hour to get rid of him.','我花了半小时才把他打发走。','I want to get rid of this old sofa.','我想处理掉这张旧沙发。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l28','to this day','',NULL,'/tə ðɪs deɪ/','To this day it has never written a word.','直到今天它一个字也没写过。','To this day I don''t know his name.','直到今天我还不知道他的名字。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l28','as big as','',NULL,'/æz bɪɡ æz/','Some diamonds were as big as marbles.','有些钻石有玻璃球那么大。','The dog was as big as a pony.','那只狗有小马那么大。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp1','choice','{"stem":"\"I had no sooner stepped off the ship ___ a man rushed up.\"(no sooner … 后面配哪个词)","options":["that","then","when","than"],"answer_index":3,"stem_cn":"我刚下船,一个人就冲了上来。","explanation_cn":"no sooner … than “一…就…”,固定搭配用 than。✓ I had no sooner stepped off than a man rushed up. ✗ then / that / when:no sooner 后面配 than。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp1','choice','{"stem":"\"No sooner ___ I sat down than the phone rang.\"(No sooner 放句首,句子要倒装)","options":["have","had","was","did"],"answer_index":1,"stem_cn":"我刚坐下,电话就响了。","explanation_cn":"No sooner 放句首,句子要倒装,把助动词提到主语前,用 had。✓ No sooner had I sat down than… ✗ have / did / was:完成时倒装用 had。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp1','choice','{"stem":"\"He had no sooner finished his speech ___ everyone began to clap.\"(no sooner … 后面配哪个词)","options":["than","that","as","then"],"answer_index":0,"stem_cn":"他刚讲完,大家就鼓起掌来。","explanation_cn":"no sooner … than “一…就…”,后面配 than。✓ He had no sooner finished than everyone clapped. ✗ then / that / as:固定搭配用 than。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp2','choice','{"stem":"\"Some of the diamonds were ___ big as marbles.\"(“与…一样…”的比较,填第一个词)","options":["too","as","so","more"],"answer_index":1,"stem_cn":"有些钻石有玻璃球那么大。","explanation_cn":"“与…一样…”的比较结构 as + 形容词 + as,第一个空用 as。✓ as big as marbles. ✗ so / too / more:比较用 as … as。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp2','choice','{"stem":"\"The fake pen was not ___ good as it looked.\"(“不像…那么…”的比较结构)","options":["so much","than","as","more"],"answer_index":2,"stem_cn":"那支假笔没看上去那么好。","explanation_cn":"“不像…那么…”用 not as … as,后半配 as。✓ not as good as it looked. ✗ so much / more / than:否定比较仍用 as。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp2','choice','{"stem":"\"My offer was ___ low as five dollars.\"(“…到…程度”的比较结构)","options":["very","as","too","so"],"answer_index":1,"stem_cn":"我出的价低到只有五美元。","explanation_cn":"“…到…程度”的比较仍是 as … as,后半用 as。✓ as low as five dollars. ✗ so / too / very:比较结构用 as … as。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp3','choice','{"stem":"\"The words ''Made ___ the U.S.A.'' were on the cap.\"(表“产地”用哪个介词)","options":["of","by","in","from"],"answer_index":2,"stem_cn":"笔帽上写着“美国制造”。","explanation_cn":"表“产地”用 made in + 地点。✓ Made in the U.S.A. ✗ by(制作者)/ of(原料)/ from:产地用 in。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp3','choice','{"stem":"\"The silverware was made ___ hand by local craftsmen.\"(表“靠…方式制作”用哪个介词)","options":["by","from","of","in"],"answer_index":0,"stem_cn":"那些银器是当地工匠手工制作的。","explanation_cn":"表“靠…方式/由…制作”用 made by;made by hand 是“手工制作”。✓ made by hand. ✗ in(产地)/ of / from:制作方式用 by。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp3','choice','{"stem":"\"The coffee pots were made ___ copper.\"(能看出原料,用哪个介词)","options":["from","by","in","of"],"answer_index":3,"stem_cn":"那些咖啡壶是铜做的。","explanation_cn":"能看出原料时用 made of。✓ made of copper. ✗ from(看不出原料)/ by / in:看得出原料用 of。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp4','choice','{"stem":"\"It ___ me over half an hour to get rid of him.\"(it ___ sb 时间 to do,过去)","options":["has taken","taking","took","takes"],"answer_index":2,"stem_cn":"我花了半个多小时才摆脱他。","explanation_cn":"it + 花时间 + sb + to do,过去用 took。✓ It took me half an hour to get rid of him. ✗ takes(现在)/ taking / has taken:一般过去用 took。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp4','choice','{"stem":"\"It ___ about ten minutes to walk to the harbor.\"(it ___ 时间 to do,一般现在)","options":["took","take","taking","takes"],"answer_index":3,"stem_cn":"走到港口大约要十分钟。","explanation_cn":"it takes + 时间 + to do,一般现在用 takes。✓ It takes about ten minutes. ✗ took(过去)/ taking / take:第三人称单数用 takes。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp4','choice','{"stem":"\"It has ___ me years to learn to bargain well.\"(it has ___ 时间,现在完成)","options":["took","take","taken","taking"],"answer_index":2,"stem_cn":"我花了好些年才学会讨价还价。","explanation_cn":"it has + 花时间,现在完成时用 has taken。✓ It has taken me years to learn. ✗ took / take / taking:完成时用 taken。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp5','choice','{"stem":"\"___ we were walking past a shop, he cut the glass.\"(引导“当…正在…时”的连词)","options":["As","Because","If","So"],"answer_index":0,"stem_cn":"我们走过一家店时,他划破了玻璃。","explanation_cn":"引导“当…正在…时”的连词,句首用 As(= when/while)。✓ As we were walking past a shop… ✗ Because(原因)/ So / If:表时间用 As。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp5','choice','{"stem":"\"I was just going into the shop ___ he grabbed my arm.\"(过去进行被“突然发生”打断,用哪个)","options":["while","since","when","as"],"answer_index":2,"stem_cn":"我正要进店,他一把抓住我胳膊。","explanation_cn":"过去进行“正在做”被“突然发生”的动作打断,用 when 引出突发。✓ I was just going in when he grabbed my arm. ✗ while / as(强调同时)/ since:突发打断用 when。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp5','choice','{"stem":"\"The pen has never written a word ___.\"(表“到目前为止”,配合现在完成)","options":["yet later","so far","ago","then"],"answer_index":1,"stem_cn":"到目前为止,这支笔一个字也没写过。","explanation_cn":"表“到目前为止”,配合现在完成时用 so far。✓ has never written a word so far. ✗ ago / then / yet later:完成时“至今”用 so far。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp6','choice','{"stem":"\"To argue over the price to make it lower is to ___.\"(“讨价还价”用哪个词)","options":["whisper","sleep","paint","bargain"],"answer_index":3,"stem_cn":"为压低价格而争论。","explanation_cn":"为压低价格而争论就是 bargain(讨价还价)。✓ bargaining with the traders. ✗ whisper 低语;✗ sleep 睡;✗ paint 画——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp6','choice','{"stem":"\"A price or demand that seems shocking and unfair is ___.\"(“出人预料的、令人不悦的”用哪个词)","options":["fair","cheap","outrageous","reasonable"],"answer_index":2,"stem_cn":"高得离谱、令人不悦的要价。","explanation_cn":"高得离谱、令人不悦的是 outrageous。✓ my offer was outrageous. ✗ reasonable 合理;✗ cheap 便宜;✗ fair 公平——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',5,'am3_l28_gp6','choice','{"stem":"\"To wave your arms about while talking is to ___.\"(“打手势”用哪个词)","options":["kneel","freeze","whisper","gesticulate"],"answer_index":3,"stem_cn":"说话时挥舞手臂。","explanation_cn":"说话时挥舞手臂是 gesticulate(打手势)。✓ gesticulating wildly. ✗ whisper 低语;✗ freeze 僵住;✗ kneel 跪——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"wares 的意思是:","options":["衣服","工具","家具","货物,商品"],"answer_index":3,"explanation_cn":"wares = 货物、商品。✓ boats loaded with wares 装满货物的小船。\n顺带记:工具 = tools;家具 = furniture;衣服 = clothes."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"tempt 的意思是:","options":["拒绝","忘记","吸引,引诱","隐藏"],"answer_index":2,"explanation_cn":"tempt = 吸引、引诱。✓ hard not to be tempted 很难不动心。\n顺带记:拒绝 = refuse;忘记 = forget;隐藏 = hide."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"bargain 的意思是:","options":["讨价还价","唱歌","奔跑","睡觉"],"answer_index":0,"explanation_cn":"bargain = 讨价还价。✓ bargaining with the traders 跟商贩砍价。\n顺带记:唱歌 = sing;睡觉 = sleep;奔跑 = run."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"genuine 的意思是:","options":["破旧的","真的,真正的","昂贵的","假的"],"answer_index":1,"explanation_cn":"genuine = 真的、真正的。✓ it looked genuine 看着像真的。\n顺带记:假的 = fake;昂贵的 = expensive;破旧的 = shabby."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"thrust 的意思是:","options":["硬塞给","偷走","清洗","丢弃"],"answer_index":0,"explanation_cn":"thrust = 硬塞给、猛推。✓ thrust the pen into my hands 把笔硬塞进我手里。\n顺带记:偷走 = steal;清洗 = wash;丢弃 = discard."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',6,NULL,'choice','{"stem":"outrageous 的意思是:","options":["普通的","出人预料的,令人不悦的","合理的","安静的"],"answer_index":1,"explanation_cn":"outrageous = 出人预料的、令人不悦的。✓ my offer was outrageous 我的报价荒唐。\n顺带记:合理的 = reasonable;普通的 = ordinary;安静的 = quiet."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',7,NULL,'cloze','{"stem":"第 1 空","context":"I had no sooner stepped off the ship ___1___ a man tried to sell me a ring. Some of his ''diamonds'' were ___2___ big as marbles. It ___3___ me half an hour to get rid of him. Later I bought a pen marked ''Made ___4___ the U.S.A.,'' but it has never written a word.","blank_no":1,"options":["than","then","that","when"],"answer_index":0,"explanation_cn":"no sooner … than “一…就…”,固定搭配用 than。✓ I had no sooner stepped off than a man tried to sell me a ring."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',7,NULL,'cloze','{"stem":"第 2 空","context":"I had no sooner stepped off the ship ___1___ a man tried to sell me a ring. Some of his ''diamonds'' were ___2___ big as marbles. It ___3___ me half an hour to get rid of him. Later I bought a pen marked ''Made ___4___ the U.S.A.,'' but it has never written a word.","blank_no":2,"options":["as","so","too","very"],"answer_index":0,"explanation_cn":"“与…一样…”的比较结构 as + 形容词 + as。✓ as big as marbles."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',7,NULL,'cloze','{"stem":"第 3 空","context":"I had no sooner stepped off the ship ___1___ a man tried to sell me a ring. Some of his ''diamonds'' were ___2___ big as marbles. It ___3___ me half an hour to get rid of him. Later I bought a pen marked ''Made ___4___ the U.S.A.,'' but it has never written a word.","blank_no":3,"options":["took","takes","taking","take"],"answer_index":0,"explanation_cn":"it + 花时间 + to do,过去用 took。✓ It took me half an hour to get rid of him."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',7,NULL,'cloze','{"stem":"第 4 空","context":"I had no sooner stepped off the ship ___1___ a man tried to sell me a ring. Some of his ''diamonds'' were ___2___ big as marbles. It ___3___ me half an hour to get rid of him. Later I bought a pen marked ''Made ___4___ the U.S.A.,'' but it has never written a word.","blank_no":4,"options":["in","by","of","from"],"answer_index":0,"explanation_cn":"表“产地”用 made in。✓ a pen marked ''Made in the U.S.A.''"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',8,NULL,'choice','{"stem":"When did the sellers begin offering their goods?","options":["The next morning","Only in the town","Before the ship had even anchored","After everyone had gone ashore"],"answer_index":2,"explanation_cn":"课文说 Before she had even anchored, the sellers had climbed aboard——船还没抛锚,小贩就上了甲板。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',8,NULL,'choice','{"stem":"How did the ring seller try to prove his diamonds were real?","options":["He cut a line in a store window","He weighed them on a scale","He heated them","He showed a receipt"],"answer_index":0,"explanation_cn":"课文说 the man pressed one against a store window and cut a deep line in the glass——他用钻石在橱窗玻璃上划出深痕来证明是真的。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',8,NULL,'choice','{"stem":"What was wrong with the wonderful pen?","options":["It was the wrong color","It was far too heavy","It had no cap","It could not be filled with ink and never wrote"],"answer_index":3,"explanation_cn":"课文说 it was impossible to fill that beautiful pen with ink, and to this day it has never written a single word——这支笔灌不进墨、一个字都没写过。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',9,NULL,'choice','{"stem":"你想说\"我刚下船,一个人就冲了上来\"(no sooner...than):","options":["I had no sooner got off the ship when a man rushed up.","I no sooner had got off the ship than a man rushed up.","I had no sooner got off the ship than a man rushed up.","I had no sooner got off the ship then a man rushed up."],"answer_index":2,"explanation_cn":"no sooner … than 固定搭配用 than。✓ I had no sooner got off the ship than a man rushed up. 场合:说“我刚一…就…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',9,NULL,'choice','{"stem":"你想说\"有些钻石有玻璃球那么大\"(as...as):","options":["Some diamonds were as big as marbles.","Some diamonds were as big than marbles.","Some diamonds were big as as marbles.","Some diamonds were so big as marbles."],"answer_index":0,"explanation_cn":"“与…一样…”用 as + 形容词 + as。✓ Some diamonds were as big as marbles. 场合:比较两样东西大小相当。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',9,NULL,'choice','{"stem":"你想说\"我花了半小时才摆脱他\"(it takes sb time to do):","options":["It took to me half an hour to get rid of him.","It took me half an hour getting rid of him.","I took half an hour to get rid of him.","It took me half an hour to get rid of him."],"answer_index":3,"explanation_cn":"“某人花多少时间做某事”用 it took sb + 时间 + to do。✓ It took me half an hour to get rid of him. 场合:说做某事花了多长时间。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"bargain 的意思是:","options":["唱歌","睡觉","奔跑","讨价还价"],"answer_index":3,"explanation_cn":"bargain = 讨价还价。✓ bargaining with the traders."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"genuine 的意思是:","options":["破旧的","昂贵的","真的,真正的","假的"],"answer_index":2,"explanation_cn":"genuine = 真的、真正的。✓ it looked genuine."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"\"I had no sooner got off the ship ___ a man rushed up.\"(no sooner … 后面配哪个词)","options":["when","then","that","than"],"answer_index":3,"stem_cn":"我刚下船,一个人就冲了上来。","explanation_cn":"no sooner … than “一…就…”,固定搭配用 than。✓ I had no sooner got off the ship than a man rushed up. ✗ then / that / when:no sooner 后面配 than。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"\"It ___ me half an hour to get rid of him.\"(it ___ sb 时间 to do,过去)","options":["took","takes","taking","take"],"answer_index":0,"stem_cn":"我花了半小时才摆脱他。","explanation_cn":"it + 花时间 + to do,过去用 took。✓ It took me half an hour to get rid of him. ✗ takes(现在)/ taking / take:一般过去用 took。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"\"get rid of\" 的意思是:","options":["抓住","修理","骑上","摆脱,除掉"],"answer_index":3,"explanation_cn":"get rid of = 摆脱、除掉。✓ get rid of him 把他打发走。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"\"made in the U.S.A.\" 的意思是:","options":["由美国人拥有","卖到美国","美国制造(产地)","用美国的钱买"],"answer_index":2,"explanation_cn":"made in the U.S.A. = 美国制造,made in + 地点表产地。✓ the words ''Made in the U.S.A.''."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"Why did the writer decide not to buy anything on the ship?","options":["He wanted to wait until he had gone ashore","The prices were fixed","He had no money","He disliked all the goods"],"answer_index":0,"passage":"Small boats loaded with wares sped out to the great cruise ship as she was entering the harbor. Before she had even anchored, the sellers had climbed aboard, and the decks were soon covered with colorful rugs, silks, copper coffee pots, and beautiful handmade silverware. It was hard not to be tempted. Many passengers had already begun bargaining with the traders, but I decided to buy nothing until I had gone ashore. I had no sooner stepped off the ship than a man rushed up, eager to sell me a diamond ring. I had no intention of buying one, yet I could not hide the fact that I was impressed by the size of the diamonds; some were as big as marbles. To prove they were real, the man pressed one against a store window and cut a deep line in the glass. It took me over half an hour to get rid of him. The next man was selling fancy pens and watches. I examined one of the pens closely; it certainly looked genuine, and near the base of the gold cap the words ''Made in the U.S.A.'' had been neatly inscribed. The man swore the pen was worth fifty dollars, but as a special favor he would let me have it for thirty. I shook my head and held up five fingers, offering five. Waving his arms wildly, he acted as if my offer were outrageous, yet he soon dropped the price to ten. Shrugging, I began to walk away, and a moment later he ran after me and thrust the pen into my hands, gladly taking my five dollars. I felt very pleased with my wonderful bargain, until I got back to the ship. No matter how hard I tried, it was impossible to fill that beautiful pen with ink, and to this day it has never written a single word!","explanation_cn":"课文说 I decided to buy nothing until I had gone ashore——他打算上岸后再买。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"How did the writer feel about his pen at first?","options":["Frightened","Angry","Bored","Very pleased with the bargain"],"answer_index":3,"passage":"Small boats loaded with wares sped out to the great cruise ship as she was entering the harbor. Before she had even anchored, the sellers had climbed aboard, and the decks were soon covered with colorful rugs, silks, copper coffee pots, and beautiful handmade silverware. It was hard not to be tempted. Many passengers had already begun bargaining with the traders, but I decided to buy nothing until I had gone ashore. I had no sooner stepped off the ship than a man rushed up, eager to sell me a diamond ring. I had no intention of buying one, yet I could not hide the fact that I was impressed by the size of the diamonds; some were as big as marbles. To prove they were real, the man pressed one against a store window and cut a deep line in the glass. It took me over half an hour to get rid of him. The next man was selling fancy pens and watches. I examined one of the pens closely; it certainly looked genuine, and near the base of the gold cap the words ''Made in the U.S.A.'' had been neatly inscribed. The man swore the pen was worth fifty dollars, but as a special favor he would let me have it for thirty. I shook my head and held up five fingers, offering five. Waving his arms wildly, he acted as if my offer were outrageous, yet he soon dropped the price to ten. Shrugging, I began to walk away, and a moment later he ran after me and thrust the pen into my hands, gladly taking my five dollars. I felt very pleased with my wonderful bargain, until I got back to the ship. No matter how hard I tried, it was impossible to fill that beautiful pen with ink, and to this day it has never written a single word!","explanation_cn":"课文说 I felt very pleased with my wonderful bargain——他起初为这桩便宜货很得意。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"How much did the writer finally pay for the pen?","options":["Fifty dollars","Five dollars","Thirty dollars","Ten dollars"],"answer_index":1,"audio":"Small boats loaded with wares sped out to the great cruise ship as she was entering the harbor. Before she had even anchored, the sellers had climbed aboard, and the decks were soon covered with colorful rugs, silks, copper coffee pots, and beautiful handmade silverware. It was hard not to be tempted. Many passengers had already begun bargaining with the traders, but I decided to buy nothing until I had gone ashore. I had no sooner stepped off the ship than a man rushed up, eager to sell me a diamond ring. I had no intention of buying one, yet I could not hide the fact that I was impressed by the size of the diamonds; some were as big as marbles. To prove they were real, the man pressed one against a store window and cut a deep line in the glass. It took me over half an hour to get rid of him. The next man was selling fancy pens and watches. I examined one of the pens closely; it certainly looked genuine, and near the base of the gold cap the words ''Made in the U.S.A.'' had been neatly inscribed. The man swore the pen was worth fifty dollars, but as a special favor he would let me have it for thirty. I shook my head and held up five fingers, offering five. Waving his arms wildly, he acted as if my offer were outrageous, yet he soon dropped the price to ten. Shrugging, I began to walk away, and a moment later he ran after me and thrust the pen into my hands, gladly taking my five dollars. I felt very pleased with my wonderful bargain, until I got back to the ship. No matter how hard I tried, it was impossible to fill that beautiful pen with ink, and to this day it has never written a single word!","explanation_cn":"课文说 gladly taking my five dollars——他最终付了五美元。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l28',10,NULL,'choice','{"stem":"What did the ship''s decks get covered with?","options":["Flowers","Fish and fruit","Rugs, silks, and silverware","Books and maps"],"answer_index":2,"audio":"Small boats loaded with wares sped out to the great cruise ship as she was entering the harbor. Before she had even anchored, the sellers had climbed aboard, and the decks were soon covered with colorful rugs, silks, copper coffee pots, and beautiful handmade silverware. It was hard not to be tempted. Many passengers had already begun bargaining with the traders, but I decided to buy nothing until I had gone ashore. I had no sooner stepped off the ship than a man rushed up, eager to sell me a diamond ring. I had no intention of buying one, yet I could not hide the fact that I was impressed by the size of the diamonds; some were as big as marbles. To prove they were real, the man pressed one against a store window and cut a deep line in the glass. It took me over half an hour to get rid of him. The next man was selling fancy pens and watches. I examined one of the pens closely; it certainly looked genuine, and near the base of the gold cap the words ''Made in the U.S.A.'' had been neatly inscribed. The man swore the pen was worth fifty dollars, but as a special favor he would let me have it for thirty. I shook my head and held up five fingers, offering five. Waving his arms wildly, he acted as if my offer were outrageous, yet he soon dropped the price to ten. Shrugging, I began to walk away, and a moment later he ran after me and thrust the pen into my hands, gladly taking my five dollars. I felt very pleased with my wonderful bargain, until I got back to the ship. No matter how hard I tried, it was impossible to fill that beautiful pen with ink, and to this day it has never written a single word!","explanation_cn":"课文说 the decks were soon covered with colorful rugs, silks, copper coffee pots, and beautiful handmade silverware——甲板上铺满了地毯、丝绸和银器。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l29',3,6,29,'Funny or Not?','是否可笑?','动词固定介词搭配(depend on / suffer from / base on)、find·think·consider + it + 形容词 + to do(先行的 it)、laugh 与 laugh at 的区别、keep on / keep off / keep up with / keep out、could(泛指能力)与 was able to(某一次终于做到)的区别(原创承载 NCE3 L29 考点·轻净化:把''sick humor''改述为''拿倒霉、疼痛的糗事开玩笑'',保留摔断腿的经典反讽·无血腥)','我们觉得一个笑话好不好笑,很大程度上取决于我们在哪里长大。幽默感神秘地和当地人的性格绑在一起。比方说,一个纽约人可能很难对一个让满屋子得克萨斯人哄堂大笑的笑话发笑,反过来也一样。不过,大多数好笑的故事都建立在滑稽的情景之上,其中有些还具有普遍的吸引力。无论你住在哪里,都很难不被卓别林的早期电影逗笑。可是近来,一种主要来自美国的新式幽默流行起来,人们管它叫“黑色幽默”。喜剧演员把笑话建立在倒霉、疼痛的糗事之上,很多人觉得这种笑话让人反感。下面这个例子留给你自己去评判。一个摔断了右腿的人在圣诞节前几周被送进了医院。从他到那儿的第一刻起,他就不停地缠着医生,要医生告诉他什么时候能回家,因为他害怕在病床上过节。他恢复得很慢,圣诞节那天,他的腿还打着石膏。他难受地躺了一整天,想着自己错过的种种乐子。可第二天早上,医生带来好消息安慰他:他很可能赶得上过新年出院。这人重新振作起来,果不其然,除夕那晚他终于能一瘸一拐地去参加聚会。为了弥补住院的糟糕经历,他喝得比该喝的稍微多了点,尽情地乐了一场,还不停地跟每个人讲他有多讨厌医院。聚会快结束时,他嘴里还在含糊地念叨着医院,一脚踩在一块冰上滑倒,摔断了左腿。','{"q":"Listen and answer — What is ''sick humor'' based on?","options":["Jokes about unlucky or painful situations","Jokes about food","Jokes about the weather","Jokes only children tell"],"answer_index":0}'::jsonb,'{"title":"depend on / find it + adj + to do / laugh vs laugh at / keep on / could vs was able to","intro":"①许多动词有固定介词:depend on(取决于)、suffer from(受…之苦)、base sth on sth(把…建立在…上)。②find / think / consider + it + 形容词 + to do:先说一个 it,真正的内容是后面的 to do,如 find it hard to laugh。③laugh 是(开心地)笑,laugh at 是嘲笑、取笑某人。④keep on doing 继续做;keep off 远离;keep up with 跟上;keep out 不许入内。⑤could 表泛指的、一贯的能力;某一次“终于设法做到了”要用 was/were able to。","table":{"headers":["用法","意思","例子"],"rows":[["depend on / suffer from","取决于 / 受…之苦","It depends on where you grew up."],["find it + 形容词 + to do","觉得(做某事)…","find it hard to laugh"],["laugh / laugh at","笑 / 嘲笑","Don''t laugh at him."],["could / was able to","有能力 / 某次终于做到","he was able to hobble along"]]},"specialRules":[{"rule":"肯定句里表示“某一次终于做成了某事”,用 was/were able to,不用 could;could 更多表示“一贯有能力”。","mark":"was able to ≠ could"},{"rule":"find / think / consider 后先放一个先行的 it,把真正的内容(to do)放到句尾:find it hard to laugh。","mark":"find it + adj + to do"},{"rule":"美式:in the hospital(英式 in hospital 不加冠词)、movie(英式 film)、sick(英式 ill)。本课已按美语写。","mark":"in the hospital / movie / sick"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l29',1,NULL,'Whether we find a joke funny or not depends a great deal on where we grew up. A sense of humor is mysteriously tied to local character. A New Yorker, for instance, might find it hard to laugh at a joke that has a room full of Texans roaring, and the reverse is just as true.','我们觉得一个笑话好不好笑,很大程度上取决于我们在哪里长大。幽默感神秘地和当地人的性格绑在一起。比方说,一个纽约人可能很难对一个让满屋子得克萨斯人哄堂大笑的笑话发笑,反过来也一样。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l29',2,NULL,'Still, most funny stories rely on comic situations, and some of these have a universal appeal. No matter where you live, it is difficult not to laugh at Charlie Chaplin''s early movies. Lately, though, a new kind of humor that comes largely from the U.S. has come into fashion. People call it ''sick humor.''','不过,大多数好笑的故事都建立在滑稽的情景之上,其中有些还具有普遍的吸引力。无论你住在哪里,都很难不被卓别林的早期电影逗笑。可是近来,一种主要来自美国的新式幽默流行起来,人们管它叫“黑色幽默”。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l29',3,NULL,'Comedians build their jokes around unlucky mishaps and painful moments, and many folks find this sort of joke distasteful. A man who had broken his right leg was taken to the hospital a few weeks before Christmas. From the moment he arrived, he kept on pestering his doctor to tell him when he could go home, for he dreaded spending the holiday in a hospital bed.','喜剧演员把笑话建立在倒霉、疼痛的糗事之上,很多人觉得这种笑话让人反感。一个摔断了右腿的人在圣诞节前几周被送进了医院。从他到那儿的第一刻起,他就不停地缠着医生,要医生告诉他什么时候能回家,因为他害怕在病床上过节。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l29',4,NULL,'His recovery was slow, and on Christmas Day his leg was still in plaster. He spent a miserable day thinking of all the fun he was missing. The next morning, however, the doctor consoled him with good news: he would probably be out in time for the New Year. The man took heart, and sure enough, on New Year''s Eve he was able to hobble along to a party.','他恢复得很慢,圣诞节那天,他的腿还打着石膏。他难受地躺了一整天,想着自己错过的种种乐子。可第二天早上,医生带来好消息安慰他:他很可能赶得上过新年出院。这人重新振作起来,果不其然,除夕那晚他终于能一瘸一拐地去参加聚会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l29',5,NULL,'To make up for his unpleasant stay, he drank a little more than was good for him, enjoyed himself thoroughly, and kept telling everybody how much he hated hospitals. He was still mumbling about them at the end of the night when he slipped on a patch of ice and broke his left leg.','为了弥补住院的糟糕经历,他喝得比该喝的稍微多了点,尽情地乐了一场,还不停地跟每个人讲他有多讨厌医院。聚会快结束时,他嘴里还在含糊地念叨着医院,一脚踩在一块冰上滑倒,摔断了左腿。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
