INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l29','in the hospital','in hospital','住院;美语加冠词 the,英式不加') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l29','movie','film','电影;美语 movie,英式 film') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l29','sick','ill','生病的;美语常用 sick,英式常用 ill') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l29','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l29','keep on doing','',NULL,'/kiːp ɑːn/','He kept on pestering the doctor.','他不停地缠着医生。','She kept on laughing.','她笑个不停。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l29','depend on','',NULL,'/dɪˈpend ɑːn/','Whether it''s funny depends on where you grew up.','好不好笑取决于你在哪里长大。','Everything depends on the weather.','一切都取决于天气。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l29','take heart','',NULL,'/teɪk hɑːrt/','The man took heart at the good news.','听到好消息,那人振作了起来。','Take heart — things will get better.','振作点,情况会好起来的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l29','laugh at','',NULL,'/læf æt/','Don''t laugh at other people.','别嘲笑别人。','They laughed at his silly hat.','他们取笑他那顶滑稽的帽子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp1','choice','{"stem":"\"Whether a joke is funny depends ___ where you grew up.\"(depend ___ 搭配哪个介词)","options":["on","to","at","of"],"answer_index":0,"stem_cn":"笑话好不好笑取决于你在哪里长大。","explanation_cn":"depend 后固定接 on,表“取决于”。✓ It depends on where you grew up. ✗ of / at / to:depend 搭配 on。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp1','choice','{"stem":"\"Comedians base their jokes ___ painful moments.\"(base sth ___ sth,搭配哪个介词)","options":["in","on","to","of"],"answer_index":1,"stem_cn":"喜剧演员把笑话建立在疼痛的糗事上。","explanation_cn":"base sth on sth “把…建立在…之上”,固定接 on。✓ base their jokes on painful moments. ✗ of / in / to:base 搭配 on。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp1','choice','{"stem":"\"Many people ___ a poor sense of humor.\"(suffer ___,表\"受…之苦\")","options":["suffer at","suffer to","suffer of","suffer from"],"answer_index":3,"stem_cn":"很多人苦于缺乏幽默感。","explanation_cn":"suffer from “受…之苦、患(病)”,固定接 from。✓ suffer from a poor sense of humor. ✗ suffer of / at / to:suffer 搭配 from。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp2','choice','{"stem":"\"A New Yorker might find ___ hard to laugh at the joke.\"(find + 先行词 + 形容词 + to do)","options":["one","that","it","this"],"answer_index":2,"stem_cn":"纽约人可能觉得很难对这个笑话发笑。","explanation_cn":"find + 先行的 it + 形容词 + to do;先放 it,真正内容是后面的 to do。✓ find it hard to laugh. ✗ that / this / one:先行词用 it。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp2','choice','{"stem":"\"He thought it ___ to spend Christmas in bed.\"(think it + ___ + to do,该填哪类词)","options":["miserable","misery","miserableness","miserably"],"answer_index":0,"stem_cn":"他觉得在床上过圣诞很难受。","explanation_cn":"think it + 形容词 + to do,中间要用形容词。✓ thought it miserable to spend Christmas in bed. ✗ misery(名词)/ miserably(副词)/ miserableness:这里要形容词 miserable。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp2','choice','{"stem":"\"We consider ___ important to laugh every day.\"(consider + 先行词 + 形容词 + to do)","options":["so","it","this","that"],"answer_index":1,"stem_cn":"我们认为每天笑一笑很重要。","explanation_cn":"consider + 先行的 it + 形容词 + to do。✓ consider it important to laugh every day. ✗ that / this / so:先行词用 it。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp3','choice','{"stem":"\"It''s rude to ___ someone''s accent.\"(\"嘲笑\"某人,动词后要加介词)","options":["laugh at","laugh","laugh of","laugh to"],"answer_index":0,"stem_cn":"嘲笑别人的口音是不礼貌的。","explanation_cn":"“嘲笑、取笑某人”用 laugh at + 人。✓ laugh at someone''s accent. ✗ laugh(单用是开心地笑)/ laugh to / laugh of:嘲笑加 at。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp3','choice','{"stem":"\"The whole room began to ___ when he told the joke.\"(\"(开心地)笑\"不加介词)","options":["laugh on","laugh","laugh at","laugh of"],"answer_index":1,"stem_cn":"他讲笑话时全场都笑了起来。","explanation_cn":"“(开心地)笑”不加介词,直接用 laugh。✓ the whole room began to laugh. ✗ laugh at(嘲笑)/ laugh on / laugh of:开心地笑不加介词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp3','choice','{"stem":"\"Don''t ___ me; I''m serious.\"(\"取笑、嘲笑\"我)","options":["laugh at","laugh","laugh with joy","laugh to"],"answer_index":0,"stem_cn":"别取笑我,我是认真的。","explanation_cn":"“取笑、嘲笑我”用 laugh at me。✓ Don''t laugh at me. ✗ laugh(单用)/ laugh with joy / laugh to:嘲笑加 at。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp4','choice','{"stem":"\"He kept ___ pestering the doctor with questions.\"(\"继续、不停地做\"用 keep ___ doing)","options":["off","up","on","out"],"answer_index":2,"stem_cn":"他不停地追问医生。","explanation_cn":"keep on doing “继续、不停地做”,用 on。✓ kept on pestering the doctor. ✗ off / up / out:“不停做”用 keep on。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp4','choice','{"stem":"\"Please keep ___ the grass.\"(\"别踏上、远离\"用 keep ___)","options":["on","up","in","off"],"answer_index":3,"stem_cn":"请勿践踏草坪。","explanation_cn":"keep off “远离、别踏上”,用 off。✓ keep off the grass. ✗ on / up / in:“别踏上”用 keep off。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp4','choice','{"stem":"\"It''s hard to keep ___ with the latest jokes.\"(\"跟上…的步伐\"用 keep ___ with)","options":["off","out","up","on"],"answer_index":2,"stem_cn":"很难跟上最新的段子。","explanation_cn":"keep up with “跟上…的步伐/进度”,用 up … with。✓ keep up with the latest jokes. ✗ on / off / out:“跟上”用 keep up with。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp5','choice','{"stem":"\"On New Year''s Eve he ___ to hobble to a party.\"(某一次\"终于做到了\"用 was ___ to)","options":["able","could","ability","can"],"answer_index":0,"stem_cn":"除夕那晚他终于一瘸一拐地去了派对。","explanation_cn":"某一次“终于设法做到了”用 was able to,不用 could。✓ he was able to hobble to a party. ✗ could(表一贯能力)/ can / ability:一次性成功用 was able to。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp5','choice','{"stem":"\"When he was young, he ___ tell jokes for hours.\"(泛指过去\"一贯有能力\"用哪个)","options":["can","could","was able","did able"],"answer_index":1,"stem_cn":"他年轻时能一连讲好几小时的笑话。","explanation_cn":"泛指过去“一贯有能力”用 could。✓ he could tell jokes for hours. ✗ was able(常指某一次)/ did able / can:一贯能力用 could。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp5','choice','{"stem":"\"After weeks in plaster, he finally ___ to walk again.\"(某一次终于\"做到某事\",用 be able to 的过去式)","options":["was able","can able","could to","could"],"answer_index":0,"stem_cn":"打了几周石膏,他终于又能走路了。","explanation_cn":"某一次终于“做到某事”,用 be able to 的过去式 was able to。✓ he finally was able to walk again. ✗ could(表一贯能力)/ could to / can able:一次性成功用 was able to。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp6','choice','{"stem":"\"A joke people find unpleasant and offensive is ___.\"(\"令人反感的\"用哪个词)","options":["delightful","ordinary","gentle","distasteful"],"answer_index":3,"stem_cn":"让人反感的笑话。","explanation_cn":"让人反感、不快的是 distasteful。✓ find this joke distasteful. ✗ delightful 令人愉快;✗ ordinary 普通;✗ gentle 温和——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp6','choice','{"stem":"\"To comfort someone who is sad is to ___ them.\"(\"安慰\"用哪个词)","options":["console","blame","ignore","annoy"],"answer_index":0,"stem_cn":"安慰伤心的人。","explanation_cn":"安慰伤心的人用 console。✓ console someone who is sad. ✗ annoy 惹恼;✗ ignore 忽视;✗ blame 责备——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',5,'am3_l29_gp6','choice','{"stem":"\"To walk awkwardly because of a hurt leg is to ___.\"(\"一瘸一拐地走\"用哪个词)","options":["glide","sprint","march","hobble"],"answer_index":3,"stem_cn":"因腿伤而蹒跚地走。","explanation_cn":"因腿伤而蹒跚地走是 hobble。✓ hobble along to a party. ✗ sprint 冲刺;✗ march 齐步走;✗ glide 滑行——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"comic 的意思是:","options":["悲伤的","严肃的","真实的","喜剧的,可笑的"],"answer_index":3,"explanation_cn":"comic = 喜剧的、可笑的。✓ based on comic situations 建立在滑稽情景上。\n顺带记:悲伤的 = sad;严肃的 = serious;真实的 = true."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"universal 的意思是:","options":["普遍的","临时的","私人的","稀少的"],"answer_index":0,"explanation_cn":"universal = 普遍的。✓ a universal appeal 普遍的吸引力。\n顺带记:稀少的 = rare;私人的 = private;临时的 = temporary."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"comedian 的意思是:","options":["农民","喜剧演员","医生","司机"],"answer_index":1,"explanation_cn":"comedian = 喜剧演员。✓ comedians build their jokes 喜剧演员编笑话。\n顺带记:医生 = doctor;司机 = driver;农民 = farmer."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"dread 的意思是:","options":["喜爱","忘记","期待","惧怕"],"answer_index":3,"explanation_cn":"dread = 惧怕。✓ he dreaded spending the holiday there 他害怕在那里过节。\n顺带记:期待 = look forward to;忘记 = forget;喜爱 = love."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"recovery 的意思是:","options":["失败","康复,恢复","出发","离开"],"answer_index":1,"explanation_cn":"recovery = 康复、恢复。✓ his recovery was slow 他恢复得很慢。\n顺带记:出发 = departure;失败 = failure;离开 = leaving."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',6,NULL,'choice','{"stem":"mumble 的意思是:","options":["歌唱","沉默","咕哝,含糊地说","大喊"],"answer_index":2,"explanation_cn":"mumble = 咕哝、含糊地说。✓ still mumbling about hospitals 还在含糊念叨医院。\n顺带记:大喊 = shout;歌唱 = sing;沉默 = keep silent."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',7,NULL,'cloze','{"stem":"第 1 空","context":"Whether a joke is funny depends ___1___ where you grew up. Even so, some comic situations have a ___2___ appeal. A new kind of humor from the U.S. is called ''sick humor,'' and many people find it ___3___. In one story, a man kept ___4___ pestering his doctor because he dreaded spending Christmas in the hospital.","blank_no":1,"options":["on","of","at","in"],"answer_index":0,"explanation_cn":"depend 后固定接 on。✓ Whether a joke is funny depends on where you grew up."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',7,NULL,'cloze','{"stem":"第 2 空","context":"Whether a joke is funny depends ___1___ where you grew up. Even so, some comic situations have a ___2___ appeal. A new kind of humor from the U.S. is called ''sick humor,'' and many people find it ___3___. In one story, a man kept ___4___ pestering his doctor because he dreaded spending Christmas in the hospital.","blank_no":2,"options":["universal","useless","private","silent"],"answer_index":0,"explanation_cn":"universal “普遍的”,指到处都有吸引力。✓ some comic situations have a universal appeal."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',7,NULL,'cloze','{"stem":"第 3 空","context":"Whether a joke is funny depends ___1___ where you grew up. Even so, some comic situations have a ___2___ appeal. A new kind of humor from the U.S. is called ''sick humor,'' and many people find it ___3___. In one story, a man kept ___4___ pestering his doctor because he dreaded spending Christmas in the hospital.","blank_no":3,"options":["distasteful","delightful","ordinary","cheap"],"answer_index":0,"explanation_cn":"distasteful “令人反感的”。✓ many people find it distasteful."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',7,NULL,'cloze','{"stem":"第 4 空","context":"Whether a joke is funny depends ___1___ where you grew up. Even so, some comic situations have a ___2___ appeal. A new kind of humor from the U.S. is called ''sick humor,'' and many people find it ___3___. In one story, a man kept ___4___ pestering his doctor because he dreaded spending Christmas in the hospital.","blank_no":4,"options":["on","off","up","out"],"answer_index":0,"explanation_cn":"keep on doing “不停地做”,用 on。✓ a man kept on pestering his doctor."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',8,NULL,'choice','{"stem":"What does whether we find a joke funny mainly depend on?","options":["Where we were brought up","How old we are","What time it is","How rich we are"],"answer_index":0,"explanation_cn":"课文说 whether we find a joke funny largely depends on where we grew up——是否觉得好笑主要取决于在哪里长大。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',8,NULL,'choice','{"stem":"Why did the man keep pestering his doctor?","options":["He wanted more medicine","He had lost his phone","He disliked the food","He dreaded spending Christmas in the hospital"],"answer_index":3,"explanation_cn":"课文说 he kept on pestering his doctor…for he dreaded spending the holiday in a hospital bed——他怕在医院过节,所以不停追问。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',8,NULL,'choice','{"stem":"What happened at the end of the party?","options":["He won a prize","He went home happy","He slipped on ice and broke his other leg","He fell asleep"],"answer_index":2,"explanation_cn":"课文结尾 he slipped on a patch of ice and broke his left leg——聚会快结束时他滑倒,摔断了另一条腿。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',9,NULL,'choice','{"stem":"你想说\"这取决于你在哪里长大\"(depend on):","options":["It depends at where you grew up.","It depends on where you grew up.","It depends of where you grew up.","It depends to where you grew up."],"answer_index":1,"explanation_cn":"depend 后固定接 on。✓ It depends on where you grew up. 场合:说某事“取决于…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',9,NULL,'choice','{"stem":"你想说\"别嘲笑他\"(laugh at):","options":["Don''t laugh at him.","Don''t laugh on him.","Don''t laugh to him.","Don''t laugh him."],"answer_index":0,"explanation_cn":"“嘲笑某人”用 laugh at + 人。✓ Don''t laugh at him. 场合:劝人别取笑别人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',9,NULL,'choice','{"stem":"你想说\"除夕那晚他终于一瘸一拐地去了派对\"(was able to):","options":["On New Year''s Eve he was able hobble to a party.","On New Year''s Eve he could hobble to a party.","On New Year''s Eve he was able to hobble to a party.","On New Year''s Eve he was can to hobble to a party."],"answer_index":2,"explanation_cn":"某一次“终于做到了”用 was able to,不用 could。✓ On New Year''s Eve he was able to hobble to a party. 场合:描述某一次终于成功做成的事。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"comic 的意思是:","options":["喜剧的,可笑的","真实的","悲伤的","严肃的"],"answer_index":0,"explanation_cn":"comic = 喜剧的、可笑的。✓ based on comic situations."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"console 的意思是:","options":["忽视","责备","安慰","激怒"],"answer_index":2,"explanation_cn":"console = 安慰。✓ the doctor consoled him 医生安慰他。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"\"Whether a joke is funny depends ___ where you grew up.\"(depend ___ 搭配哪个介词)","options":["to","on","at","of"],"answer_index":1,"stem_cn":"笑话好不好笑取决于你在哪里长大。","explanation_cn":"depend 后固定接 on。✓ It depends on where you grew up. ✗ of / at / to:depend 搭配 on。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"\"He kept ___ pestering the doctor.\"(\"不停地做\"用 keep ___ doing)","options":["on","off","out","up"],"answer_index":0,"stem_cn":"他不停地追问医生。","explanation_cn":"keep on doing “不停地做”,用 on。✓ He kept on pestering the doctor. ✗ off / up / out:“不停做”用 keep on。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"\"laugh at\" 的意思是:","options":["大哭","嘲笑,取笑","开心大笑","微笑"],"answer_index":1,"explanation_cn":"laugh at = 嘲笑、取笑。✓ Don''t laugh at other people 别嘲笑别人。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"\"take heart\" 的意思是:","options":["心跳加速","拿走某物","振作起来,鼓起勇气","感到害怕"],"answer_index":2,"explanation_cn":"take heart = 振作起来、鼓起勇气。✓ The man took heart 那人重新振作起来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"According to the passage, why do national differences matter for humor?","options":["A joke funny in one place may not be funny in another","Everyone finds the same jokes funny","Humor never changes anywhere","Only Americans have a sense of humor"],"answer_index":0,"passage":"Whether we find a joke funny or not depends a great deal on where we grew up. A sense of humor is mysteriously tied to local character. A New Yorker, for instance, might find it hard to laugh at a joke that has a room full of Texans roaring, and the reverse is just as true. Still, most funny stories rely on comic situations, and some of these have a universal appeal. No matter where you live, it is difficult not to laugh at Charlie Chaplin''s early movies. Lately, though, a new kind of humor that comes largely from the U.S. has come into fashion. People call it ''sick humor.'' Comedians build their jokes around unlucky mishaps and painful moments, and many folks find this sort of joke distasteful. The following example will let you judge for yourself. A man who had broken his right leg was taken to the hospital a few weeks before Christmas. From the moment he arrived, he kept on pestering his doctor to tell him when he could go home, for he dreaded spending the holiday in a hospital bed. His recovery was slow, and on Christmas Day his leg was still in plaster. He spent a miserable day thinking of all the fun he was missing. The next morning, however, the doctor consoled him with good news: he would probably be out in time for the New Year. The man took heart, and sure enough, on New Year''s Eve he was able to hobble along to a party. To make up for his unpleasant stay, he drank a little more than was good for him, enjoyed himself thoroughly, and kept telling everybody how much he hated hospitals. He was still mumbling about them at the end of the night when he slipped on a patch of ice and broke his left leg.","explanation_cn":"课文说 a Frenchman/New Yorker might fail to see anything amusing in a joke others love——同一个笑话在不同地方未必都好笑。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"How did the story end?","options":["He recovered fully and went home","He broke his other leg on a patch of ice","He never made it to the party","He stayed in the hospital for months"],"answer_index":1,"passage":"Whether we find a joke funny or not depends a great deal on where we grew up. A sense of humor is mysteriously tied to local character. A New Yorker, for instance, might find it hard to laugh at a joke that has a room full of Texans roaring, and the reverse is just as true. Still, most funny stories rely on comic situations, and some of these have a universal appeal. No matter where you live, it is difficult not to laugh at Charlie Chaplin''s early movies. Lately, though, a new kind of humor that comes largely from the U.S. has come into fashion. People call it ''sick humor.'' Comedians build their jokes around unlucky mishaps and painful moments, and many folks find this sort of joke distasteful. The following example will let you judge for yourself. A man who had broken his right leg was taken to the hospital a few weeks before Christmas. From the moment he arrived, he kept on pestering his doctor to tell him when he could go home, for he dreaded spending the holiday in a hospital bed. His recovery was slow, and on Christmas Day his leg was still in plaster. He spent a miserable day thinking of all the fun he was missing. The next morning, however, the doctor consoled him with good news: he would probably be out in time for the New Year. The man took heart, and sure enough, on New Year''s Eve he was able to hobble along to a party. To make up for his unpleasant stay, he drank a little more than was good for him, enjoyed himself thoroughly, and kept telling everybody how much he hated hospitals. He was still mumbling about them at the end of the night when he slipped on a patch of ice and broke his left leg.","explanation_cn":"课文结尾 he slipped on a patch of ice and broke his left leg——他滑倒摔断了另一条腿(反讽收尾)。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"When was the man taken to the hospital?","options":["On New Year''s Day","In the middle of summer","A few weeks before Christmas","Right after the party"],"answer_index":2,"audio":"Whether we find a joke funny or not depends a great deal on where we grew up. A sense of humor is mysteriously tied to local character. A New Yorker, for instance, might find it hard to laugh at a joke that has a room full of Texans roaring, and the reverse is just as true. Still, most funny stories rely on comic situations, and some of these have a universal appeal. No matter where you live, it is difficult not to laugh at Charlie Chaplin''s early movies. Lately, though, a new kind of humor that comes largely from the U.S. has come into fashion. People call it ''sick humor.'' Comedians build their jokes around unlucky mishaps and painful moments, and many folks find this sort of joke distasteful. The following example will let you judge for yourself. A man who had broken his right leg was taken to the hospital a few weeks before Christmas. From the moment he arrived, he kept on pestering his doctor to tell him when he could go home, for he dreaded spending the holiday in a hospital bed. His recovery was slow, and on Christmas Day his leg was still in plaster. He spent a miserable day thinking of all the fun he was missing. The next morning, however, the doctor consoled him with good news: he would probably be out in time for the New Year. The man took heart, and sure enough, on New Year''s Eve he was able to hobble along to a party. To make up for his unpleasant stay, he drank a little more than was good for him, enjoyed himself thoroughly, and kept telling everybody how much he hated hospitals. He was still mumbling about them at the end of the night when he slipped on a patch of ice and broke his left leg.","explanation_cn":"课文说 was taken to the hospital a few weeks before Christmas——圣诞节前几周被送进医院。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l29',10,NULL,'choice','{"stem":"How did the man feel on Christmas Day?","options":["Angry at his friends","Miserable, thinking of the fun he was missing","Cheerful and excited","Sleepy and calm"],"answer_index":1,"audio":"Whether we find a joke funny or not depends a great deal on where we grew up. A sense of humor is mysteriously tied to local character. A New Yorker, for instance, might find it hard to laugh at a joke that has a room full of Texans roaring, and the reverse is just as true. Still, most funny stories rely on comic situations, and some of these have a universal appeal. No matter where you live, it is difficult not to laugh at Charlie Chaplin''s early movies. Lately, though, a new kind of humor that comes largely from the U.S. has come into fashion. People call it ''sick humor.'' Comedians build their jokes around unlucky mishaps and painful moments, and many folks find this sort of joke distasteful. The following example will let you judge for yourself. A man who had broken his right leg was taken to the hospital a few weeks before Christmas. From the moment he arrived, he kept on pestering his doctor to tell him when he could go home, for he dreaded spending the holiday in a hospital bed. His recovery was slow, and on Christmas Day his leg was still in plaster. He spent a miserable day thinking of all the fun he was missing. The next morning, however, the doctor consoled him with good news: he would probably be out in time for the New Year. The man took heart, and sure enough, on New Year''s Eve he was able to hobble along to a party. To make up for his unpleasant stay, he drank a little more than was good for him, enjoyed himself thoroughly, and kept telling everybody how much he hated hospitals. He was still mumbling about them at the end of the night when he slipped on a patch of ice and broke his left leg.","explanation_cn":"课文说 He spent a miserable day thinking of all the fun he was missing——圣诞那天他难受地想着错过的乐子。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l30',3,6,30,'The Death of a Ghost','幽灵之死','give 短语(give up / give in / give away)、say 与 tell 的区别、do 与 make 的搭配、be supposed to(应该/据说)、used to do(过去习惯)与过去进行、过去完成时的被动(work had been done)(原创承载 NCE3 L30 考点·净化换情节:去掉''战时开小差/被当局追捕''的外壳,改为埃里克年轻时与家人争吵后出走、被误以为已故,秘密归家隐居;鬼屋悬念与隐士承载原样保留·无违法元素)','多年来,村里人一直相信恩德利农场闹鬼。农场归乔和鲍勃·考克斯两兄弟所有,他们雇了几个工人,可谁都不肯久留。每个工人辞工时,讲的都是同一个故事:他们总是一觉醒来,发现活儿一夜之间就干完了。趁大家睡觉的时候,干草已被割好,牛棚也已打扫干净。有个熬了一整夜的工人声称,他看见月光下有个身影在割庄稼。渐渐地,一个说法被大家接受了:考克斯兄弟有一个尽职尽责的幽灵替他们干了大部分的活。谁也没料到,农场上还有一个从没露过面的人。可事实正是如此。不久前,村民们惊讶地得知,恩德利的幽灵去世了。人人都去参加了葬礼,因为那个“幽灵”不是别人,正是埃里克·考克斯——据说早在年轻时就去世的第三个兄弟。葬礼过后,乔和鲍勃说出了一个保守了五十多年的秘密。埃里克本是家中长子。年轻时,他和家人大吵一架,负气出海远走,多年来大家都以为他已经不在人世。其实他早已悄悄回了家,只是太要强、太羞愧,不愿再面对村里人。父亲把他藏了起来,对外只说埃里克已经死了。父亲去世后,乔和鲍勃觉得替他保守秘密是自己的责任。这么多年,埃里克一直像隐士一样生活。他过去总是白天睡觉、夜里干活,浑然不知自己已成了恩德利的幽灵。可当他去世时,两个兄弟发现,这个秘密再也瞒不下去了。','{"q":"Listen and answer — Who was the ghost of Endley Farm?","options":["A third brother who had been hidden for years","A real spirit","A visiting actor","A lost traveler"],"answer_index":0}'::jsonb,'{"title":"give up / say vs tell / do vs make / be supposed to / used to do","intro":"①give 短语:give up(放弃)、give in(屈服)、give away(赠送/泄露)。②say 与 tell:tell a lie / tell the time / tell a story;say goodbye / say so。③do 与 make:do the work / do sb a favor / do one''s best;make a mistake / make a speech。④be supposed to “(按规矩)应该”或“据说、被认为”。⑤used to do 表示过去的习惯;某时刻“正在做”用过去进行(was/were doing)。⑥过去完成时的被动:had been + 过去分词,如 the work had been done。","table":{"headers":["用法","意思","例子"],"rows":[["give up / give in / give away","放弃 / 屈服 / 赠送","he gave up his job"],["tell a lie / say goodbye","撒谎 / 道别","he told the same story"],["do a favor / make a mistake","帮忙 / 犯错","do most of the work"],["be supposed to / used to do","应该·据说 / 过去常","he used to work at night"]]},"specialRules":[{"rule":"tell 常接 a lie / a story / the time / the truth;say 常接 goodbye / so / 一句话。别把 say 和 tell 混用。","mark":"say ≠ tell"},{"rule":"used to do 是过去的习惯(现在不再);was/were doing 是过去某一刻正在进行。两者不同。","mark":"used to do ≠ was doing"},{"rule":"美式:laborer(英式 labourer,少个 u)、corn(美语常指玉米,英式泛指谷物、玉米叫 maize)。本课已按美语写。","mark":"laborer / corn"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l30',1,NULL,'For years, the people of the village believed that Endley Farm was haunted. The farm was owned by two brothers, Joe and Bob Cox, who hired a few laborers, but no one was willing to stay for long. Every time a worker gave up his job, he told the same story.','多年来,村里人一直相信恩德利农场闹鬼。农场归乔和鲍勃·考克斯两兄弟所有,他们雇了几个工人,可谁都不肯久留。每个工人辞工时,讲的都是同一个故事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l30',2,NULL,'The farmhands said that they always woke up to find that the work had been done overnight. Hay had been cut and the cowsheds had been cleaned while everyone slept. One worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight. In time, it became an accepted fact that the Cox brothers were served by a conscientious ghost that did most of their work for them.','工人们说,他们总是一觉醒来,发现活儿一夜之间就干完了。趁大家睡觉的时候,干草已被割好,牛棚也已打扫干净。有个熬了一整夜的工人声称,他看见月光下有个身影在割庄稼。渐渐地,一个说法被大家接受了:考克斯兄弟有一个尽职尽责的幽灵替他们干了大部分的活。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l30',3,NULL,'No one suspected that there might be someone else on the farm who had never been seen. Yet that was exactly the case. A short time ago, the villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral, for the ''ghost'' was none other than Eric Cox, a third brother who was supposed to have died as a young man. After the funeral, Joe and Bob revealed a secret that they had kept for over fifty years.','谁也没料到,农场上还有一个从没露过面的人。可事实正是如此。不久前,村民们惊讶地得知,恩德利的幽灵去世了。人人都去参加了葬礼,因为那个“幽灵”不是别人,正是埃里克·考克斯——据说早在年轻时就去世的第三个兄弟。葬礼过后,乔和鲍勃说出了一个保守了五十多年的秘密。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l30',4,NULL,'Eric had been the eldest son of the family. As a young man he had quarreled bitterly with his relatives and had run off to sea, and for years everyone believed he had been lost. In truth he had come home in secret, too proud and too ashamed to face the village again. His father hid him and told everybody that Eric had died.','埃里克本是家中长子。年轻时,他和家人大吵一架,负气出海远走,多年来大家都以为他已经不在人世。其实他早已悄悄回了家,只是太要强、太羞愧,不愿再面对村里人。父亲把他藏了起来,对外只说埃里克已经死了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l30',5,NULL,'When their father passed away, Joe and Bob thought it their duty to keep Eric in hiding. All these years, Eric had lived as a recluse. He used to sleep during the day and work at night, quite unaware that he had become the ghost of Endley. When he died, however, his brothers found it impossible to keep the secret any longer.','父亲去世后,乔和鲍勃觉得替他保守秘密是自己的责任。这么多年,埃里克一直像隐士一样生活。他过去总是白天睡觉、夜里干活,浑然不知自己已成了恩德利的幽灵。可当他去世时,两个兄弟发现,这个秘密再也瞒不下去了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
