INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l30','fall','autumn','秋天(收割季);美语 fall,英式 autumn') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l30','flashlight','torch','手电筒;美语 flashlight,英式 torch') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l30','give up','',NULL,'/ɡɪv ʌp/','Every worker gave up his job.','每个工人都辞去了工作。','Don''t give up so easily.','别这么轻易放弃。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l30','used to do','',NULL,'/ˈjuːst tə/','He used to work at night.','他过去总在夜里干活。','There used to be a farm here.','这里以前有一座农场。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l30','none other than','',NULL,'/nʌn ˈʌðər ðæn/','The ghost was none other than Eric.','那幽灵不是别人,正是埃里克。','The winner was none other than my brother.','获胜者不是别人,正是我哥哥。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l30','in hiding','',NULL,'/ɪn ˈhaɪdɪŋ/','Eric remained in hiding for years.','埃里克藏匿了很多年。','The cat stayed in hiding under the bed.','那只猫躲在床底下不出来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp1','choice','{"stem":"\"No one was willing to stay, so each worker gave ___ his job.\"(\"放弃\"工作用 give ___)","options":["in","up","away","out"],"answer_index":1,"stem_cn":"每个工人都放弃了工作。","explanation_cn":"give up “放弃、辞去”,用 up。✓ each worker gave up his job. ✗ in(屈服)/ away(赠送)/ out(分发):“放弃”用 give up。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp1','choice','{"stem":"\"The enemy finally gave ___ and surrendered.\"(\"屈服、投降\"用 give ___)","options":["in","up","away","off"],"answer_index":0,"stem_cn":"敌人最终屈服投降了。","explanation_cn":"give in “屈服、投降”,用 in。✓ the enemy finally gave in. ✗ up(放弃)/ away(赠送)/ off:“屈服”用 give in。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp1','choice','{"stem":"\"He gave ___ all his old books to the library.\"(\"赠送、捐出\"用 give ___)","options":["up","away","out","in"],"answer_index":1,"stem_cn":"他把旧书都捐给了图书馆。","explanation_cn":"give away “赠送、捐出”,用 away。✓ gave away all his old books. ✗ up(放弃)/ in(屈服)/ out:“赠送”用 give away。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp2','choice','{"stem":"\"Every worker ___ the same story about the ghost.\"(\"讲(故事)\"用哪个动词)","options":["told","spoke","said","talked"],"answer_index":0,"stem_cn":"每个工人都讲同样的鬼故事。","explanation_cn":"“讲(故事)”用 tell,过去式 told;tell a story。✓ told the same story. ✗ said / spoke / talked:讲故事用 tell。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp2','choice','{"stem":"\"It''s wrong to ___ a lie.\"(\"撒谎\"的固定搭配)","options":["say","speak","tell","talk"],"answer_index":2,"stem_cn":"撒谎是不对的。","explanation_cn":"“撒谎”固定搭配 tell a lie。✓ It''s wrong to tell a lie. ✗ say / speak / talk:lie 前用 tell。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp2','choice','{"stem":"\"He waved and ___ goodbye to his friends.\"(\"道别\"的固定搭配)","options":["told","said","talked","spoke"],"answer_index":1,"stem_cn":"他挥手和朋友们道别。","explanation_cn":"“道别”固定搭配 say goodbye,过去式 said。✓ said goodbye to his friends. ✗ told / spoke / talked:goodbye 前用 say。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp3','choice','{"stem":"\"The ghost ___ most of the work on the farm.\"(\"做(工作)\"用哪个动词)","options":["made","gave","took","did"],"answer_index":3,"stem_cn":"幽灵做了农场大部分的活。","explanation_cn":"“做(工作)”用 do,过去式 did;do the work。✓ did most of the work. ✗ made / took / gave:做工作用 do。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp3','choice','{"stem":"\"Everyone can ___ a mistake now and then.\"(\"犯错误\"的固定搭配)","options":["do","make","give","take"],"answer_index":1,"stem_cn":"谁都难免会犯错。","explanation_cn":"“犯错误”固定搭配 make a mistake。✓ can make a mistake. ✗ do / take / give:mistake 前用 make。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp3','choice','{"stem":"\"Could you ___ me a favor?\"(\"帮个忙\"的固定搭配)","options":["give","make","take","do"],"answer_index":3,"stem_cn":"你能帮我个忙吗?","explanation_cn":"“帮忙”固定搭配 do sb a favor。✓ Could you do me a favor? ✗ make / take / give:favor 前用 do。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp4','choice','{"stem":"\"Eric was ___ to have died as a young man.\"(\"据说、被认为\"用 be ___ to)","options":["supposed","suppose","supposing","supposition"],"answer_index":0,"stem_cn":"据说埃里克年轻时就去世了。","explanation_cn":"be supposed to “据说、被认为”,用过去分词 supposed。✓ was supposed to have died young. ✗ suppose / supposing / supposition:固定用 be supposed to。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp4','choice','{"stem":"\"You are ___ to knock before you enter.\"(\"(按规矩)应该\"用 be ___ to)","options":["suppose","supposing","supposedly","supposed"],"answer_index":3,"stem_cn":"进门前你应该先敲门。","explanation_cn":"be supposed to “(按规矩)应该”,用 supposed。✓ You are supposed to knock. ✗ supposing / suppose / supposedly:固定用 be supposed to。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp4','choice','{"stem":"\"The train is ___ to arrive at noon.\"(\"照理应当\"用 be ___ to)","options":["supposing","suppose","supposed","supposal"],"answer_index":2,"stem_cn":"火车照理应当中午到。","explanation_cn":"be supposed to “照理应当”,用 supposed。✓ The train is supposed to arrive at noon. ✗ suppose / supposing / supposal:固定用 be supposed to。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp5','choice','{"stem":"\"Eric ___ sleep during the day and work at night.\"(过去\"习惯性地做\"用 ___ do)","options":["is used to","used to","uses to","was used to"],"answer_index":1,"stem_cn":"埃里克过去白天睡、夜里干活。","explanation_cn":"过去的习惯用 used to + 动词原形。✓ Eric used to sleep during the day. ✗ was used to(习惯于…)/ is used to / uses to:过去习惯用 used to do。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp5','choice','{"stem":"\"He ___ working in the fields when the worker saw him.\"(某时刻\"正在做\"用过去进行)","options":["was","is","used to","has been"],"answer_index":0,"stem_cn":"那工人看到他时,他正在田里干活。","explanation_cn":"某一时刻“正在做”用过去进行 was doing。✓ He was working in the fields when… ✗ used to(过去习惯)/ is / has been:此刻正在做用 was。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp5','choice','{"stem":"\"There ___ to be an old barn here years ago.\"(过去\"曾经存在\"用 ___ to be)","options":["uses","used","is used","was used"],"answer_index":1,"stem_cn":"多年前这里曾有一座旧谷仓。","explanation_cn":"过去“曾经存在”用 there used to be。✓ There used to be an old barn here. ✗ was used / is used / uses:表“曾经有”用 used to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp6','choice','{"stem":"\"A person who works hard and carefully is ___.\"(\"认真尽责的\"用哪个词)","options":["lazy","rude","careless","conscientious"],"answer_index":3,"stem_cn":"做事认真负责的人。","explanation_cn":"做事认真、尽责的是 conscientious。✓ a conscientious ghost. ✗ careless 粗心;✗ lazy 懒;✗ rude 粗鲁——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp6','choice','{"stem":"\"A person who lives alone and avoids others is a ___.\"(\"隐士\"用哪个词)","options":["recluse","leader","guest","teacher"],"answer_index":0,"stem_cn":"独居、避世的人。","explanation_cn":"独自生活、避开他人的人是 recluse(隐士)。✓ lived as a recluse. ✗ leader 领导;✗ guest 客人;✗ teacher 老师——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',5,'am3_l30_gp6','choice','{"stem":"\"To make a hidden secret known is to ___ it.\"(\"揭露、透露\"用哪个词)","options":["hide","reveal","keep","forget"],"answer_index":1,"stem_cn":"把秘密公之于众。","explanation_cn":"把隐藏的秘密公开是 reveal(揭露、透露)。✓ revealed a secret. ✗ hide 隐藏;✗ forget 忘记;✗ keep 保留——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"haunted 的意思是:","options":["闹鬼的","崭新的","明亮的","宽敞的"],"answer_index":0,"explanation_cn":"haunted = 闹鬼的。✓ the farm was haunted 农场闹鬼。\n顺带记:明亮的 = bright;宽敞的 = spacious;崭新的 = brand-new."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"conscientious 的意思是:","options":["懒惰的","认真尽责的","胆小的","粗心的"],"answer_index":1,"explanation_cn":"conscientious = 认真尽责的。✓ a conscientious ghost 尽职的幽灵。\n顺带记:懒惰的 = lazy;粗心的 = careless;胆小的 = timid."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"suspect 的意思是:","options":["证明","相信","欢迎","怀疑,料想"],"answer_index":3,"explanation_cn":"suspect = 怀疑、料想。✓ no one suspected 没人料到。\n顺带记:相信 = believe;证明 = prove;欢迎 = welcome."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"astonish 的意思是:","options":["使疲倦","使惊讶","使无聊","使平静"],"answer_index":1,"explanation_cn":"astonish = 使惊讶。✓ villagers were astonished 村民们大为惊讶。\n顺带记:使平静 = calm;使疲倦 = tire;使无聊 = bore."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"funeral 的意思是:","options":["葬礼","生日","婚礼","毕业"],"answer_index":0,"explanation_cn":"funeral = 葬礼。✓ everyone went to the funeral 人人都去参加葬礼。\n顺带记:婚礼 = wedding;生日 = birthday;毕业 = graduation."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',6,NULL,'choice','{"stem":"moonlight 的意思是:","options":["暴雨","雷声","日出","月光"],"answer_index":3,"explanation_cn":"moonlight = 月光。✓ a figure in the moonlight 月光下的身影。\n顺带记:日出 = sunrise;雷声 = thunder;暴雨 = storm."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',7,NULL,'cloze','{"stem":"第 1 空","context":"For years the village believed Endley Farm was haunted. Every time a worker gave ___1___ his job, he said the work had been done overnight. In fact the ''ghost'' was ___2___ other than Eric Cox, a brother who was ___3___ to have died young. He ___4___ to sleep by day and work by night, never knowing he had become the ghost of Endley.","blank_no":1,"options":["up","in","away","out"],"answer_index":0,"explanation_cn":"give up “放弃、辞去”,用 up。✓ Every time a worker gave up his job…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',7,NULL,'cloze','{"stem":"第 2 空","context":"For years the village believed Endley Farm was haunted. Every time a worker gave ___1___ his job, he said the work had been done overnight. In fact the ''ghost'' was ___2___ other than Eric Cox, a brother who was ___3___ to have died young. He ___4___ to sleep by day and work by night, never knowing he had become the ghost of Endley.","blank_no":2,"options":["none","no","not","never"],"answer_index":0,"explanation_cn":"none other than “不是别人,正是…”,固定用 none。✓ the ''ghost'' was none other than Eric Cox."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',7,NULL,'cloze','{"stem":"第 3 空","context":"For years the village believed Endley Farm was haunted. Every time a worker gave ___1___ his job, he said the work had been done overnight. In fact the ''ghost'' was ___2___ other than Eric Cox, a brother who was ___3___ to have died young. He ___4___ to sleep by day and work by night, never knowing he had become the ghost of Endley.","blank_no":3,"options":["supposed","suppose","supposing","supposition"],"answer_index":0,"explanation_cn":"be supposed to “据说、被认为”,用 supposed。✓ a brother who was supposed to have died young."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',7,NULL,'cloze','{"stem":"第 4 空","context":"For years the village believed Endley Farm was haunted. Every time a worker gave ___1___ his job, he said the work had been done overnight. In fact the ''ghost'' was ___2___ other than Eric Cox, a brother who was ___3___ to have died young. He ___4___ to sleep by day and work by night, never knowing he had become the ghost of Endley.","blank_no":4,"options":["used","was used","uses","is used"],"answer_index":0,"explanation_cn":"过去的习惯用 used to + 原形。✓ He used to sleep by day and work by night."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',8,NULL,'choice','{"stem":"Why did the farmhands keep quitting?","options":["The farm was too far away","The pay was too low","They woke to find the work already done overnight","They disliked the brothers"],"answer_index":2,"explanation_cn":"课文说 they always woke up to find that the work had been done overnight——工人们总一觉醒来发现活儿一夜干完了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',8,NULL,'choice','{"stem":"Who was the ''ghost'' of Endley really?","options":["Eric Cox, a hidden third brother","A neighbor from the village","Joe''s young son","A traveling stranger"],"answer_index":0,"explanation_cn":"课文说 the ''ghost'' was none other than Eric Cox, a third brother——幽灵其实是被藏起来的第三个兄弟埃里克。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',8,NULL,'choice','{"stem":"How did Eric spend his days and nights?","options":["He never did any work","He slept by day and worked by night","He worked by day and slept at night","He was always away"],"answer_index":1,"explanation_cn":"课文说 He used to sleep during the day and work at night——他白天睡、夜里干活。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',9,NULL,'choice','{"stem":"你想说\"每个工人都放弃了工作\"(give up):","options":["Every worker gave up his job.","Every worker gave up of his job.","Every worker give up his job.","Every worker gave his job away."],"answer_index":0,"explanation_cn":"give up 后面直接跟名词,不加 of;give up + 名词。✓ Every worker gave up his job. 场合:说某人“放弃、辞去”某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',9,NULL,'choice','{"stem":"你想说\"据说他年轻时就去世了\"(be supposed to):","options":["He is supposed to died young.","He supposed to have died young.","He is suppose to have died young.","He is supposed to have died young."],"answer_index":3,"explanation_cn":"be supposed to 用过去分词 supposed,后接不定式;“据说他年轻时就去世了”用完成不定式 to have died。✓ He is supposed to have died young. 场合:转述“据说…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',9,NULL,'choice','{"stem":"你想说\"他过去白天睡、夜里干活\"(used to do):","options":["He use to sleep by day and work by night.","He used to sleep by day and work by night.","He used sleep by day and work by night.","He was used to sleep by day and work by night."],"answer_index":1,"explanation_cn":"过去的习惯用 used to + 原形(不是 use to,也不是 was used to)。✓ He used to sleep by day and work by night. 场合:说过去一贯的习惯。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"haunted 的意思是:","options":["明亮的","崭新的","闹鬼的","宽敞的"],"answer_index":2,"explanation_cn":"haunted = 闹鬼的。✓ the farm was haunted."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"reveal 的意思是:","options":["隐藏","保留","遗忘","揭露,透露"],"answer_index":3,"explanation_cn":"reveal = 揭露、透露。✓ revealed a secret 说出了秘密。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"\"Every worker gave ___ his job.\"(\"放弃\"用 give ___)","options":["up","in","out","away"],"answer_index":0,"stem_cn":"每个工人都放弃了工作。","explanation_cn":"give up “放弃、辞去”,用 up。✓ Every worker gave up his job. ✗ in(屈服)/ away(赠送)/ out(分发):“放弃”用 give up。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"\"Eric was ___ to have died young.\"(\"据说\"用 be ___ to)","options":["suppose","supposed","supposition","supposing"],"answer_index":1,"stem_cn":"据说埃里克年轻时就去世了。","explanation_cn":"be supposed to “据说”,用过去分词 supposed。✓ Eric was supposed to have died young. ✗ suppose / supposing / supposition:固定用 be supposed to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"\"give up\" 在\"gave up his job\"里的意思是:","options":["赠送","屈服","放弃","举起"],"answer_index":2,"explanation_cn":"give up 在 gave up his job 里意为“放弃、辞去”。✓ gave up his job 辞去工作。\n(give away 才是赠送,give in 才是屈服。)"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"\"in hiding\" 的意思是:","options":["大声喊叫","躲藏着,隐匿","四处旅行","公开露面"],"answer_index":1,"explanation_cn":"in hiding = 躲藏着、隐匿。✓ keep Eric in hiding 让埃里克躲藏着。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"Why did the farmhands never stay long at Endley Farm?","options":["They kept waking to find the work mysteriously done","The wages were poor","The farmhouse was cold","The brothers were cruel to them"],"answer_index":0,"passage":"For years, the people of the village believed that Endley Farm was haunted. The farm was owned by two brothers, Joe and Bob Cox, who hired a few laborers, but no one was willing to stay for long. Every time a worker gave up his job, he told the same story. The farmhands said that they always woke up to find that the work had been done overnight. Hay had been cut and the cowsheds had been cleaned while everyone slept. One worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight. In time, it became an accepted fact that the Cox brothers were served by a conscientious ghost that did most of their work for them. No one suspected that there might be someone else on the farm who had never been seen. Yet that was exactly the case. A short time ago, the villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral, for the ''ghost'' was none other than Eric Cox, a third brother who was supposed to have died as a young man. After the funeral, Joe and Bob revealed a secret that they had kept for over fifty years. Eric had been the eldest son of the family. As a young man he had quarreled bitterly with his relatives and had run off to sea, and for years everyone believed he had been lost. In truth he had come home in secret, too proud and too ashamed to face the village again. His father hid him and told everybody that Eric had died. When their father passed away, Joe and Bob thought it their duty to keep Eric in hiding. All these years, Eric had lived as a recluse. He used to sleep during the day and work at night, quite unaware that he had become the ghost of Endley. When he died, however, his brothers found it impossible to keep the secret any longer.","explanation_cn":"课文说 they always woke up to find that the work had been done overnight——工人们总发现活儿神秘地被干完了,所以待不长。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"What was the real secret behind the ''ghost''?","options":["The brothers had made the whole thing up","There was no ghost story at all","The farm had a secret machine","A hidden brother had been living and working on the farm"],"answer_index":3,"passage":"For years, the people of the village believed that Endley Farm was haunted. The farm was owned by two brothers, Joe and Bob Cox, who hired a few laborers, but no one was willing to stay for long. Every time a worker gave up his job, he told the same story. The farmhands said that they always woke up to find that the work had been done overnight. Hay had been cut and the cowsheds had been cleaned while everyone slept. One worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight. In time, it became an accepted fact that the Cox brothers were served by a conscientious ghost that did most of their work for them. No one suspected that there might be someone else on the farm who had never been seen. Yet that was exactly the case. A short time ago, the villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral, for the ''ghost'' was none other than Eric Cox, a third brother who was supposed to have died as a young man. After the funeral, Joe and Bob revealed a secret that they had kept for over fifty years. Eric had been the eldest son of the family. As a young man he had quarreled bitterly with his relatives and had run off to sea, and for years everyone believed he had been lost. In truth he had come home in secret, too proud and too ashamed to face the village again. His father hid him and told everybody that Eric had died. When their father passed away, Joe and Bob thought it their duty to keep Eric in hiding. All these years, Eric had lived as a recluse. He used to sleep during the day and work at night, quite unaware that he had become the ghost of Endley. When he died, however, his brothers found it impossible to keep the secret any longer.","explanation_cn":"课文说 the ''ghost'' was none other than Eric Cox…had lived as a recluse——所谓幽灵其实是隐居在农场干活的兄弟。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"How did the villagers learn the ghost had ''died''?","options":["They saw it vanish into the air","No one ever found out","They were astonished by the news and went to the funeral","A newspaper reported it"],"answer_index":2,"audio":"For years, the people of the village believed that Endley Farm was haunted. The farm was owned by two brothers, Joe and Bob Cox, who hired a few laborers, but no one was willing to stay for long. Every time a worker gave up his job, he told the same story. The farmhands said that they always woke up to find that the work had been done overnight. Hay had been cut and the cowsheds had been cleaned while everyone slept. One worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight. In time, it became an accepted fact that the Cox brothers were served by a conscientious ghost that did most of their work for them. No one suspected that there might be someone else on the farm who had never been seen. Yet that was exactly the case. A short time ago, the villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral, for the ''ghost'' was none other than Eric Cox, a third brother who was supposed to have died as a young man. After the funeral, Joe and Bob revealed a secret that they had kept for over fifty years. Eric had been the eldest son of the family. As a young man he had quarreled bitterly with his relatives and had run off to sea, and for years everyone believed he had been lost. In truth he had come home in secret, too proud and too ashamed to face the village again. His father hid him and told everybody that Eric had died. When their father passed away, Joe and Bob thought it their duty to keep Eric in hiding. All these years, Eric had lived as a recluse. He used to sleep during the day and work at night, quite unaware that he had become the ghost of Endley. When he died, however, his brothers found it impossible to keep the secret any longer.","explanation_cn":"课文说 villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral——村民惊讶地得知幽灵去世,都去参加葬礼。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l30',10,NULL,'choice','{"stem":"What work did the ''ghost'' do overnight?","options":["Cooked meals for the family","Fed the whole village","Painted the farmhouse","Cut hay and cleaned the cowsheds"],"answer_index":3,"audio":"For years, the people of the village believed that Endley Farm was haunted. The farm was owned by two brothers, Joe and Bob Cox, who hired a few laborers, but no one was willing to stay for long. Every time a worker gave up his job, he told the same story. The farmhands said that they always woke up to find that the work had been done overnight. Hay had been cut and the cowsheds had been cleaned while everyone slept. One worker, who stayed up all night, claimed to have seen a figure cutting corn in the moonlight. In time, it became an accepted fact that the Cox brothers were served by a conscientious ghost that did most of their work for them. No one suspected that there might be someone else on the farm who had never been seen. Yet that was exactly the case. A short time ago, the villagers were astonished to learn that the ghost of Endley had died. Everyone went to the funeral, for the ''ghost'' was none other than Eric Cox, a third brother who was supposed to have died as a young man. After the funeral, Joe and Bob revealed a secret that they had kept for over fifty years. Eric had been the eldest son of the family. As a young man he had quarreled bitterly with his relatives and had run off to sea, and for years everyone believed he had been lost. In truth he had come home in secret, too proud and too ashamed to face the village again. His father hid him and told everybody that Eric had died. When their father passed away, Joe and Bob thought it their duty to keep Eric in hiding. All these years, Eric had lived as a recluse. He used to sleep during the day and work at night, quite unaware that he had become the ghost of Endley. When he died, however, his brothers found it impossible to keep the secret any longer.","explanation_cn":"课文说 Hay had been cut and cowsheds had been cleaned——干草被割好、牛棚被打扫干净。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
